            assert "tab_url" in manifest["frames"][-1]
            assert manifest["frames"][-1]["metadata"]["step"] == 3
            assert manifest["frames"][-1]["metadata"]["cursor"] == {"x": 10, "y": 20}
            html_text = html_path.read_text()
