def test_browser_activity_finally_skips_terminal_on_pause_for_resume():
    """Source guard: real-activity pause returns flip the flag that gates finally."""
    import re
    from pathlib import Path

    source = Path("domains/spawn_browser_agent_v3/handler.py").read_text(encoding="utf-8")
    # Simulated world-model path returns the same statuses but has no
    # ``_schedule_browser_cleanup`` terminal safety net — only the real
    # activity's finally was emitting false task_complete on pause.
    match = re.search(
        r"async def _spawn_browser_agent_activity_v3_real\b.*?(?=\nasync def |\nclass )",
        source,
        flags=re.DOTALL,
    )
    assert match is not None
    real = match.group(0)
    assert "browser_task_paused_for_resume = False" in real
    assert real.count("browser_task_paused_for_resume = True") >= 3
    assert "emit_task_terminal=not browser_task_paused_for_resume" in real
    for status in (
        "awaiting_write_approval",
        "awaiting_payment_card_approval",
        "awaiting_auth_assistance",
    ):
        idx = 0
        found = False
        while True:
            idx = real.find(f'"status": "{status}"', idx)
            if idx < 0:
                break
            return_idx = real.find("return resume_result", idx)
            assert return_idx > idx, status
            window = real[idx:return_idx]
            assert "persist_resume_context(" in window, status
            assert "browser_task_paused_for_resume = True" in window, status
            found = True
            idx += 1
        assert found, status


async def test_drain_background_browser_cleanups_waits_then_times_out():
    import contextlib

    from domains.spawn_browser_agent_v3.handler import (
        _background_browser_cleanup_tasks,
        drain_background_browser_cleanups,
    )

    # No pending tasks -> returns immediately.
    await asyncio.wait_for(drain_background_browser_cleanups(timeout=0.1), timeout=1)

    release = asyncio.Event()

    async def _slow_cleanup() -> None:
        await release.wait()

    task = asyncio.create_task(_slow_cleanup())
    _background_browser_cleanup_tasks.add(task)
    task.add_done_callback(lambda done: _background_browser_cleanup_tasks.discard(done))
    try:
        # Drain blocks while the cleanup is in-flight, then times out without
        # raising (worker shutdown must not hang forever on a stuck teardown).
        await asyncio.wait_for(drain_background_browser_cleanups(timeout=0.2), timeout=2)
        assert not task.done()  # still running; drain did not cancel it

        # Once the cleanup finishes, drain returns promptly by awaiting it.
        release.set()
        await asyncio.wait_for(drain_background_browser_cleanups(timeout=1.0), timeout=2)
        assert task.done()
    finally:
        release.set()
        with contextlib.suppress(Exception):
            await task
        _background_browser_cleanup_tasks.discard(task)


