def test_mouse_input_synthesis_generates_bounded_non_linear_path():
    import random

    from browser_tools.input_synthesis import synthesize_mouse_path

    path = synthesize_mouse_path(
        (20, 30),
        (620, 410),
        screen=(800, 600),
        frequency_hz=90,
        duration_s=0.45,
        stop_count=1,
        rng=random.Random(7),
    )

    assert (path[0].x, path[0].y) == (20, 30)
    assert len(path) > 20
    assert (path[-1].x, path[-1].y) == (620, 410)
    assert all(0 <= sample.x < 800 and 0 <= sample.y < 600 for sample in path)
    assert all(sample.delay_s > 0 for sample in path)

    start = (20, 30)
    end = (620, 410)
    dx = end[0] - start[0]
    dy = end[1] - start[1]
    line_len = (dx * dx + dy * dy) ** 0.5
    max_line_error = max(
        abs(dy * sample.x - dx * sample.y + end[0] * start[1] - end[1] * start[0]) / line_len for sample in path[2:-2]
    )
    assert max_line_error > 3
    assert max_line_error < line_len * 0.14

    projections = [((sample.x - start[0]) * dx + (sample.y - start[1]) * dy) / (line_len * line_len) for sample in path]
    assert min(projections) >= -0.08
    assert max(projections) <= 1.08


def test_mouse_input_synthesis_rejects_unrealistic_sample_jumps():
    import math
    import random

    from browser_tools.input_synthesis import (
        MIMIC_MAX_VELOCITY_PX_PER_S,
        synthesize_mouse_path,
    )

    start = (20, 20)
    end = (610, 332)
    distance = math.hypot(end[0] - start[0], end[1] - start[1])
    duration_s = max(0.08, min(0.72, 0.05 + distance / 1600))

    for seed in range(1, 31):
        path = synthesize_mouse_path(
            start,
            end,
            screen=(1280, 800),
            frequency_hz=75,
            duration_s=duration_s,
            snr=65,
            rng=random.Random(seed),
        )
        steps = [
            math.hypot(current.x - previous.x, current.y - previous.y) for previous, current in zip(path, path[1:])
        ]
        velocities = [
            math.hypot(current.x - previous.x, current.y - previous.y) / max(1e-6, current.delay_s)
            for previous, current in zip(path, path[1:])
        ]
        assert max(steps) <= 62
        assert max(velocities) <= MIMIC_MAX_VELOCITY_PX_PER_S + 60


def test_mouse_path_duration_tracks_request_within_velocity_cap():
    """A stroke takes about as long as its peak-velocity bound allows, not a
    slow linear crawl, and long moves stay near human Fitts'-law times
    (350px used to take ~1.85s at p50, 800px ~1.9s)."""
    import math
    import random
    import statistics

    from browser_tools.input_synthesis import MIMIC_MAX_VELOCITY_PX_PER_S, synthesize_mouse_path

    for distance, p50_ceiling_s in ((60, 0.2), (350, 0.55), (800, 1.1)):
        requested = max(0.08, min(0.95, 0.05 + distance / 1100))
        totals = []
        for seed in range(120):
            path = synthesize_mouse_path(
                (100, 300),
                (100 + distance, 300),
                screen=(1280, 800),
                frequency_hz=105,
                duration_s=requested,
                rng=random.Random(seed),
            )
            totals.append(sum(sample.delay_s for sample in path))
            velocities = [math.hypot(b.x - a.x, b.y - a.y) / b.delay_s for a, b in zip(path, path[1:])]
            assert max(velocities) <= MIMIC_MAX_VELOCITY_PX_PER_S + 1e-6
            halfway = next(i for i, s in enumerate(path) if s.x - 100 >= distance / 2)
            assert sum(s.delay_s for s in path[: halfway + 1]) < 0.75 * totals[-1] or distance < 100
        assert statistics.median(totals) <= p50_ceiling_s, (distance, statistics.median(totals))


