async def test_init_browser_session_transient_failure_returns_retryable():
    """A provider infra hiccup (5xx, or the Kernel `400 Proxy is marked
    unavailable` health-check error) is classified retryable-transient so the
    init loop reallocates a fresh proxy instead of failing the browser run."""
    from domains.spawn_browser_agent_v3.repo import init_browser_session

    setup_mock({"/api/browser-session/init": {"status": 500, "text": "oops"}})
    cfg = _fake_config()
    out = await init_browser_session(cfg, "u", "a", "")
    assert out["transient_init_failure"] is True
    assert out["status_code"] == 500

    setup_mock(
        {
            "/api/browser-session/init": {
                "status": 400,
                "text": '{"error":"400 Proxy is marked unavailable from the last health check"}',
            }
        }
    )
    out = await init_browser_session(cfg, "u", "a", "")
    assert out["transient_init_failure"] is True
    assert out["status_code"] == 400


async def test_init_browser_session_timeout_returns_retryable():
    """Worker httpx ReadTimeout on /init must be transient, not ActivityError.

    Kernel create can exceed the 180s client budget (webdecoy 2a421e78 /
    biometrics 05823816). httpx.ReadTimeout must NOT raise out of
    init_browser_session — that fails the Temporal activity, forces an
    LLM-level respawn of spawn_browser_agent, and burns the smoke dynamic
    cap. Classify as transient_init_failure so the handler's bounded
    fresh-proxy retry loop reallocates in-activity.
    """
    import httpx
    from domains.spawn_browser_agent_v3 import repo

    class _Client:
        async def __aenter__(self):
            return self

        async def __aexit__(self, *a):
            return False

        async def post(self, *a, **kw):
            raise httpx.ReadTimeout("simulated kernel create stall")

    with patch.object(repo.httpx, "AsyncClient", return_value=_Client()):
        out = await repo.init_browser_session(_fake_config(), "u", "a", "https://example.com")

    assert out["transient_init_failure"] is True
    assert out["status_code"] == 0
    assert "ReadTimeout" in out["detail"]


async def test_init_browser_session_unique_constraint_is_not_transient():
    """A P2002 on the preallocated BrowserSession.id is never a proxy hiccup.

    Prod agent 43b3a83b burned five transient retries on
    ``Unique constraint failed on the fields: (id)`` because every 5xx was
    treated as retryable. The reclaim path must handle this; classifying it
    transient only masks the idempotency bug.
    """
    from domains.spawn_browser_agent_v3.repo import (
        init_browser_session,
        is_transient_session_init_failure,
    )

    body = (
        '{"error":"\\nInvalid `prisma.browserSession.create()` invocation:\\n\\n\\n'
        'Unique constraint failed on the fields: (`id`)"}'
    )
    assert is_transient_session_init_failure(500, body) is False

    setup_mock({"/api/browser-session/init": {"status": 500, "text": body}})
    cfg = _fake_config()
    try:
        await init_browser_session(cfg, "u", "a", "", task_id="11111111-1111-4111-8111-111111111111")
        raise AssertionError("unique-constraint 500 must be fatal, not transient")
    except Exception as e:
        assert "Failed to init session" in str(e)
        assert "Unique constraint failed" in str(e)


