async def test_rotation_storage_capture_is_bounded_when_indexeddb_stalls():
    """Challenge recovery must regain control if Playwright storage capture stalls."""
    from domains.spawn_browser_agent_v3.handler import (
        BrowserStorageCaptureTimeoutError,
        _capture_rotation_storage_state,
        _rotation_storage_capture_timeout_seconds,
    )

    assert _rotation_storage_capture_timeout_seconds(float("inf")) == 15.0
    assert _rotation_storage_capture_timeout_seconds("1e999") == 15.0
    assert _rotation_storage_capture_timeout_seconds(600) == 60.0

    previous_timeout = os.environ.get("BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS")

    async def stalled_storage_state(*, indexed_db):
        assert indexed_db is True
        await asyncio.Event().wait()

    context = SimpleNamespace(storage_state=stalled_storage_state)
    page = SimpleNamespace(context=context)
    os.environ["BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS"] = "0.01"
    try:
        try:
            await asyncio.wait_for(
                _capture_rotation_storage_state(page),
                timeout=1.0,
            )
        except BrowserStorageCaptureTimeoutError as exc:
            assert "timed out after 0.01s" in str(exc)
        else:
            raise AssertionError("expected a typed bounded storage-capture timeout")

        # An empty cookie jar with no answered origin is nothing to carry: still the typed timeout.
        async def no_cookies():
            return []

        empty = SimpleNamespace(context=SimpleNamespace(storage_state=stalled_storage_state, cookies=no_cookies))
        try:
            await asyncio.wait_for(_capture_rotation_storage_state(empty), timeout=1.0)
        except BrowserStorageCaptureTimeoutError:
            pass
        else:
            raise AssertionError("an empty jar must not turn the timeout into an empty carried state")

        # A failed (not timed-out) full capture with cookies carries them; with none, no state.
        async def failing_storage_state(*, indexed_db):
            raise RuntimeError("storage read failed")

        async def one_cookie():
            return [{"name": "session", "value": "kept", "domain": "shop.example", "path": "/"}]

        carried = await asyncio.wait_for(
            _capture_rotation_storage_state(
                SimpleNamespace(context=SimpleNamespace(storage_state=failing_storage_state, cookies=one_cookie))
            ),
            timeout=1.0,
        )
        assert carried == {"cookies": [{"name": "session", "value": "kept", "domain": "shop.example", "path": "/"}], "origins": []}, carried
        assert (
            await asyncio.wait_for(
                _capture_rotation_storage_state(
                    SimpleNamespace(context=SimpleNamespace(storage_state=failing_storage_state, cookies=no_cookies))
                ),
                timeout=1.0,
            )
            is None
        )
    finally:
        if previous_timeout is None:
            os.environ.pop("BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS", None)
        else:
            os.environ["BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS"] = previous_timeout


async def test_recovery_storage_timeout_finishes_error_and_returns_control_to_model_loop():
    """The factored recovery path persists timeout evidence and closes the tool as ERROR."""
    from domains.spawn_browser_agent_v3.handler import (
        BrowserStorageCaptureTimeoutError,
        _capture_recovery_storage_state,
        _finalize_browser_recovery_action_result,
    )

    previous_timeout = os.environ.get("BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS")

    async def stalled_storage_state(*, indexed_db):
        assert indexed_db is True
        await asyncio.Event().wait()

    progress = AsyncMock()
    action_history = _mocked_action_history()
    browser_stream = SimpleNamespace(finish_tools=AsyncMock())
    browser_turn_messages = []
    dom_service = SimpleNamespace()
    unified_action = {
        "action": "recover_from_challenge",
        "thinking": "recover safely",
        "params": {"reason": "DataDome challenge"},
    }
    page = SimpleNamespace(context=SimpleNamespace(storage_state=stalled_storage_state))
    os.environ["BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS"] = "0.01"
    try:
        try:
            await _capture_recovery_storage_state(page, progress)
        except BrowserStorageCaptureTimeoutError as exc:
            action_result = {"success": False, "error": str(exc)}
        else:
            raise AssertionError("expected storage capture timeout")

        await _finalize_browser_recovery_action_result(
            action_result=action_result,
            dom_service=dom_service,
            action_history=action_history,
            thinking="recover safely",
            recovery_reason="DataDome challenge",
            browser_turn_messages=browser_turn_messages,
            task_prompt="Book a hotel",
            browser_state={"url": "https://expedia.com/login"},
            unified_action=unified_action,
            recovery_call_id="recovery-call-1",
            browser_stream=browser_stream,
        )
    finally:
        if previous_timeout is None:
            os.environ.pop("BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS", None)
        else:
            os.environ["BROWSER_ROTATION_STORAGE_CAPTURE_TIMEOUT_SECONDS"] = previous_timeout

    progress.assert_awaited_once_with(
        "capture_browser_state",
        "Capturing cookies, local storage, and IndexedDB before challenge recovery",
    )
    recorded = action_history.record_action.await_args.kwargs["result"]
    assert recorded["success"] is False
    assert "timed out after 0.01s" in recorded["error"]
    browser_stream.finish_tools.assert_awaited_once_with(status="ERROR")
    assert browser_turn_messages[-1]["role"] == "tool"
    assert "timed out after 0.01s" in browser_turn_messages[-1]["content"]


def test_post_verifier_rejection_browser_state_fetch_is_bounded():
    """After a durable verifier rejection, refreshing browser state must stay soft-bounded.

    polar-odysseys-440ed7f388a2 TREE STALL: challenge freeze left CDP hung, so
    the post-reject `get_browser_state` burned the full 300s BrowserStateRequest
    timeout with no further durable messages while Temporal keepalive heartbeats
    kept the activity alive. Tree-stall correctly paused at ~510s of silence.
    The rejection message was already persisted — this refresh is optional and
    must go through `_get_browser_state_soft` (≈10s × 2), never a bare CDP await
    inside the verifier try/except.
    """
    import ast
    import inspect
    import textwrap

    from domains.spawn_browser_agent_v3 import config, handler

    assert config.BROWSER_STATE_SOFT_TIMEOUT_SECONDS == 10.0
    assert config.BROWSER_STATE_SOFT_ATTEMPTS == 2

    source = textwrap.dedent(inspect.getsource(handler._spawn_browser_agent_activity_v3_real))
    tree = ast.parse(source)
    reject_title_nodes = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.JoinedStr)
        and any(isinstance(part, ast.Constant) and "Verifier rejected" in str(part.value) for part in node.values)
    ]
    assert reject_title_nodes, "expected Verifier rejected title in attempt_completion path"
    reject_lineno = min(node.lineno for node in reject_title_nodes)

    soft_calls = []
    bare_gets = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Await) or node.lineno < reject_lineno:
            continue
        if node.lineno >= reject_lineno + 80:
            continue
        call = node.value
        if not isinstance(call, ast.Call):
            continue
        func = call.func
        if isinstance(func, ast.Name) and func.id == "_get_browser_state_soft":
            soft_calls.append(node.lineno)
            continue
        if (
            isinstance(func, ast.Attribute)
            and func.attr == "get_browser_state"
            and isinstance(func.value, ast.Name)
            and func.value.id == "dom_service"
        ):
            bare_gets.append(node.lineno)

    assert soft_calls, (
        "post-verifier-rejection path must await _get_browser_state_soft; found none after Verifier rejected"
    )
    assert not bare_gets, (
        "post-verifier-rejection path must not bare-await get_browser_state; "
        f"found unbounded await at line(s) {bare_gets}"
    )


async def test_get_browser_state_soft_retries_then_returns_none_on_hang():
    """Soft fetch times out per attempt, retries once, then returns None."""
    import asyncio
    from types import SimpleNamespace

    from domains.spawn_browser_agent_v3.handler import _get_browser_state_soft

    calls = {"n": 0}

    async def hang(*, include_screenshot: bool = False):
        calls["n"] += 1
        await asyncio.Event().wait()

    started = asyncio.get_event_loop().time()
    out = await _get_browser_state_soft(
        SimpleNamespace(get_browser_state=hang),
        include_screenshot=False,
        timeout_seconds=0.05,
        attempts=2,
    )
    elapsed = asyncio.get_event_loop().time() - started
    assert out is None
    assert calls["n"] == 2
    assert 0.08 <= elapsed < 0.5, elapsed


async def test_get_browser_state_soft_retries_after_timeout_then_succeeds():
    """A single soft timeout is retried and can still return state."""
    import asyncio
    from types import SimpleNamespace

    from domains.spawn_browser_agent_v3.handler import _get_browser_state_soft

    calls = {"n": 0}

    async def flaky(*, include_screenshot: bool = False):
        calls["n"] += 1
        if calls["n"] == 1:
            await asyncio.sleep(1)
        return {"url": "https://example.com", "screenshot": None}

    out = await _get_browser_state_soft(
        SimpleNamespace(get_browser_state=flaky),
        include_screenshot=False,
        timeout_seconds=0.05,
        attempts=2,
    )
    assert out == {"url": "https://example.com", "screenshot": None}
    assert calls["n"] == 2


