async def test_browser_thinking_stream_routes_chunks_to_browser_message_list():
    from domains.spawn_browser_agent_v3.streaming import BrowserThinkingStream
    from providers.rose import StreamChunk

    stream = BrowserThinkingStream(
        agent_id="agent-1",
        task_id="browser-task-1",
        iteration=4,
        started_at_ms=123_000,
    )

    with (
        patch(
            "domains.spawn_browser_agent_v3.streaming.stream_assistant_chunk",
            new_callable=AsyncMock,
        ) as publish,
        patch(
            "domains.spawn_browser_agent_v3.streaming.stream_tool_event",
            new_callable=AsyncMock,
        ) as publish_tool,
    ):
        await stream.start()
        await stream.on_chunk(
            StreamChunk(
                kind="metadata",
                data={"actual_model": "gpt-5.6-sol-gpt"},
            )
        )
        await stream.on_chunk(StreamChunk(kind="reasoning", data={"text": "Inspecting page"}))
        await stream.on_chunk(
            StreamChunk(
                kind="tool_call",
                data={"id": "call-1", "name": "click", "arguments": '{"index":3}'},
            )
        )
        await stream.finish()
        assert publish_tool.await_count == 1
        await stream.finish_tools(status="FINISHED")

    published = [call.kwargs for call in publish.await_args_list]
    assert published[0]["delta"] == ""
    assert published[0]["done"] is False
    assert published[-1]["done"] is True
    assert all(item["agent_id"] == "agent-1" for item in published)
    assert all(item["sub_agent_id"] == "browser-task-1" for item in published)
    assert all(item["llm_started_at_ms"] == 123_000 for item in published)

    assert all(item["clear_on_done"] is True for item in published)
    assert any(item["is_gpt"] is True for item in published[1:])
    assert "Inspecting page" in "".join(item["delta"] for item in published)
    assert '"click"' in "".join(item["delta"] for item in published)
    assert publish_tool.await_count == 2
    assert publish_tool.await_args_list[0].kwargs == {
        "agent_id": "agent-1",
        "stream_id": stream.stream_id,
        "tool_call_id": "call-1",
        "tool_name": "click",
        "title": "Starting click...",
        "char_count": len('{"id":"call-1","name":"click","arguments":"{\\"index\\":3}"}'),
        "is_gpt": True,
        "is_claude": False,
        "llm_started_at_ms": 123_000,
        "sub_agent_id": "browser-task-1",
    }
    assert publish_tool.await_args_list[1].kwargs == {
        "agent_id": "agent-1",
        "stream_id": stream.stream_id,
        "tool_call_id": "call-1",
        "tool_name": "click",
        "title": "Finished click",
        "status": "FINISHED",
        "sub_agent_id": "browser-task-1",
    }


async def test_browser_thinking_stream_restart_closes_the_abandoned_attempt():
    """A reply cut off at the output limit is retried; the retry must not append to
    the abandoned attempt's stream, or the displayed decision mixes the two."""
    from domains.spawn_browser_agent_v3.streaming import BrowserThinkingStream
    from providers.rose import StreamChunk

    stream = BrowserThinkingStream(agent_id="agent-1", task_id="browser-task-1", iteration=2)
    with (
        patch(
            "domains.spawn_browser_agent_v3.streaming.stream_assistant_chunk",
            new_callable=AsyncMock,
        ) as publish,
        patch(
            "domains.spawn_browser_agent_v3.streaming.stream_tool_event",
            new_callable=AsyncMock,
        ) as tool_events,
    ):
        await stream.on_chunk(StreamChunk(kind="reasoning", data={"text": "half an ans"}))
        await stream.on_chunk(
            StreamChunk(kind="tool_call", data={"id": "call-abandoned", "name": "click", "arguments": {}})
        )
        first_stream_id = stream.stream_id
        await stream.on_chunk(StreamChunk(kind="restart", data={"reason": "output_limit"}))
        await stream.on_chunk(StreamChunk(kind="reasoning", data={"text": "full answer"}))
        await stream.finish_tools(status="FINISHED")
        await stream.finish()

    # The abandoned attempt's tool call never gets a result from the retry: it is
    # closed as failed under the stream that opened it, and the retry's
    # finish_tools has nothing left from it to publish under the new stream.
    tool_calls = [call.kwargs for call in tool_events.await_args_list]
    abandoned = [item for item in tool_calls if item["tool_call_id"] == "call-abandoned"]
    assert abandoned, tool_calls
    closing = [item for item in abandoned if item.get("status") in {"FAILED", "FINISHED"}]
    assert closing and all(item["stream_id"] == first_stream_id for item in closing), abandoned
    assert all(item["status"] == "FAILED" for item in closing), closing

    published = [call.kwargs for call in publish.await_args_list]
    first = [item for item in published if item["stream_id"] == first_stream_id]
    retry = [item for item in published if item["stream_id"] != first_stream_id]
    assert first and first[-1]["done"] is True, "the abandoned stream was not closed"
    assert "full answer" not in "".join(item["delta"] for item in first)
    assert retry and any(item["delta"] == "full answer" for item in retry), retry
    assert retry[-1]["done"] is True


async def test_credential_propagation_failure_keeps_the_browser_run_outcome():
    """A backend error while recording credential liveness is bookkeeping: the
    finished browser run keeps its outcome instead of failing and being retried
    (a Prisma transaction expired under load and failed a completed sign-in, 2026-10-06)."""
    import httpx

    from domains.spawn_browser_agent_v3 import handler
    from helpers.workflow_generation import WorkflowGenerationSealed
    from tools.base import MessageStatus

    saved: list = []

    async def record(**kwargs):
        saved.append(kwargs)

    request = httpx.Request("POST", "http://backend.test/api/credential-propagation/browser-run")
    response = httpx.Response(500, request=request, text="Transaction already closed")
    with (
        patch.object(
            handler,
            "propagate_browser_run_credentials",
            AsyncMock(side_effect=httpx.HTTPStatusError("500", request=request, response=response)),
        ),
        patch.object(handler, "save_browser_action_message", record),
    ):
        result = await handler._propagate_browser_credentials_with_progress(
            config=MagicMock(),
            agent_id="agent-1",
            task_id="browser-task-1",
            browser_url="https://shop.example/account",
            status="completed",
            success=True,
            message="Signed in.",
        )
    assert result["outcome"] == "unknown" and result["refs"] == 0 and result["applied"] == 0, result
    assert "500" in result["error"], result
    assert [item["status"] for item in saved] == [MessageStatus.IN_PROGRESS, MessageStatus.ERROR], saved
    assert saved[-1]["title"] == "Credential state update failed"

    # The diagnostic write is best-effort: when the same backend refuses that
    # message too, the fallback result is still returned instead of raising.
    async def record_then_fail(**kwargs):
        if kwargs.get("status") == MessageStatus.ERROR:
            raise RuntimeError("backend unavailable")
        saved.append(kwargs)

    with (
        patch.object(
            handler,
            "propagate_browser_run_credentials",
            AsyncMock(side_effect=httpx.HTTPStatusError("500", request=request, response=response)),
        ),
        patch.object(handler, "save_browser_action_message", record_then_fail),
    ):
        fallback = await handler._propagate_browser_credentials_with_progress(
            config=MagicMock(),
            agent_id="agent-1",
            task_id="browser-task-1",
            browser_url="https://shop.example/account",
            status="completed",
            success=True,
            message="Signed in.",
        )
    assert fallback["outcome"] == "unknown" and "500" in fallback["error"], fallback

    # A replaced workflow generation still stops the run.
    with (
        patch.object(
            handler,
            "propagate_browser_run_credentials",
            AsyncMock(side_effect=WorkflowGenerationSealed("sealed")),
        ),
        patch.object(handler, "save_browser_action_message", record),
    ):
        try:
            await handler._propagate_browser_credentials_with_progress(
                config=MagicMock(),
                agent_id="agent-1",
                task_id="browser-task-1",
                browser_url="",
                status="completed",
                success=True,
                message="Signed in.",
            )
        except WorkflowGenerationSealed:
            pass
        else:
            raise AssertionError("a sealed generation must not be swallowed as bookkeeping")


async def test_credential_propagation_redacts_classifier_and_diagnostic_payloads():
    """Credential bookkeeping cannot relay a fatal browser error into a classifier or diagnostics."""
    from browser_tools.secret_refs import mask_secret_values
    from domains.spawn_browser_agent_v3 import handler
    from tools.base import MessageStatus

    refs = {"card_number": "4111111111111111", "pwd:fixture": "synthetic-fatal-propagation-password"}
    echoed = "failure: " + " | ".join(refs.values())

    def redact(value):
        return mask_secret_values(value, refs)

    for fail, diagnostic_fails in ((False, False), (True, False), (True, True)):
        propagate = AsyncMock(
            **(
                {"side_effect": RuntimeError(echoed)}
                if fail
                else {"return_value": {"outcome": "unknown", "refs": 0, "applied": 0, "detail": echoed}}
            )
        )

        async def save(**kwargs):
            if diagnostic_fails and kwargs.get("status") == MessageStatus.ERROR:
                raise RuntimeError(echoed)

        saved = AsyncMock(side_effect=save)
        log = MagicMock()
        with (
            patch.object(handler, "propagate_browser_run_credentials", propagate),
            patch.object(handler, "save_browser_action_message", saved),
            patch.object(handler, "logger", log),
        ):
            result = await handler._propagate_browser_credentials_with_progress(
                config=SimpleNamespace(),
                agent_id="agent-1",
                task_id="task-1",
                browser_url="https://fixture.test/",
                status="error",
                success=False,
                message=echoed,
                redact=redact,
            )
        retained = str(
            {
                "classifier": propagate.await_args.kwargs,
                "diagnostics": saved.await_args_list,
                "result": result,
                "logs": log.mock_calls,
            }
        )
        assert all(secret not in retained for secret in refs.values()), (
            "fatal credential propagation exposed a known credential"
        )
        assert propagate.await_args.kwargs["message"] == redact(echoed)
        assert result["outcome"] == "unknown"


def test_browser_activity_error_redaction_preserves_temporal_retry_metadata():
    """The actual Temporal failure encoder receives no credential-bearing message, cause, or details."""
    from temporalio.api.failure.v1 import Failure
    from temporalio.converter import DefaultFailureConverter, DefaultPayloadConverter
    from temporalio.exceptions import ApplicationError, ApplicationErrorCategory
    from browser_tools.secret_refs import mask_secret_values
    from domains.spawn_browser_agent_v3.handler import _redact_browser_activity_error
    from helpers.workflow_generation import WorkflowGenerationSealed

    refs = {"card_number": "4111111111111111", "pwd:fixture": "synthetic-fatal-temporal-password"}

    def redact(value):
        return mask_secret_values(value, refs)

    delay = timedelta(seconds=17)
    for message in ("failure: " + refs["card_number"], "A safe outer failure"):
        raw = ApplicationError(
            message,
            {"nested": [refs["pwd:fixture"]]},
            type="SyntheticBrowserFatal",
            non_retryable=True,
            next_retry_delay=delay,
            category=ApplicationErrorCategory.BENIGN,
        )
        raw.__cause__ = ValueError(refs["pwd:fixture"])
        try:
            raise raw
        except Exception as original:
            try:
                raise _redact_browser_activity_error(original, redact) from None
            except Exception as sanitized:
                failure = Failure()
                DefaultFailureConverter().to_failure(sanitized, DefaultPayloadConverter(), failure)
                serialized = failure.SerializeToString()
                assert all(secret.encode() not in serialized for secret in refs.values()), (
                    "Temporal serialized a secret from a fatal message, cause, or details"
                )
                assert isinstance(sanitized, ApplicationError)
                assert sanitized.type == "SyntheticBrowserFatal"
                assert sanitized.non_retryable is True
                assert sanitized.next_retry_delay == delay
                assert sanitized.category == ApplicationErrorCategory.BENIGN
                assert not failure.HasField("cause"), "the raw credential-bearing exception chain survived redaction"
    ordinary = RuntimeError("public browser failure")
    assert _redact_browser_activity_error(ordinary, redact) is ordinary
    sealed = WorkflowGenerationSealed("workflow generation replaced")
    assert _redact_browser_activity_error(sealed, redact) is sealed


async def test_browser_streaming_rose_client_forwards_and_folds_chunks():
    from domains.spawn_browser_agent_v3.streaming import BrowserStreamingRoseClient
    from providers.rose import RoseClient, StreamChunk

    client = BrowserStreamingRoseClient()
    sink = MagicMock()
    sink.on_chunk = AsyncMock()
    client.set_thinking_stream(sink)

    async def fake_complete(_client, **_kwargs):
        yield StreamChunk(
            kind="metadata",
            data={"actual_model": "gpt-5.6-sol-gpt", "pool_name": "rose-1-browser-use"},
        )
        yield StreamChunk(kind="reasoning", data={"text": "Inspect"})
        yield StreamChunk(
            kind="tool_call",
            data={"id": "call-1", "name": "click", "arguments": '{"index":3}'},
        )
        yield StreamChunk(
            kind="tool_call",
            data={"id": "call-2", "name": "wait", "arguments": '{"time_ms":1000}'},
        )
        yield StreamChunk(kind="usage", data={"prompt_tokens": 10, "completion_tokens": 4})
        yield StreamChunk(kind="done", data={})

    with patch.object(RoseClient, "complete", new=fake_complete):
        result = await client.complete_browser_use(
            task="Click the target",
            browser_state={"url": "https://example.com", "dom_tree": "<button>Target</button>"},
            action_history=[],
            available_actions=["click", "wait"],
        )

    assert result["actual_model"] == "gpt-5.6-sol-gpt"
    assert result["action"]["action"] == "click"
    assert result["tool_call_id"] == "call-1"
    assert sink.on_chunk.await_count == 6
    forwarded_tools = [
        call.args[0].data["id"] for call in sink.on_chunk.await_args_list if call.args[0].kind == "tool_call"
    ]
    assert forwarded_tools == ["call-1", "call-2"]
    assert [item["tool_call_ids"] for item in result["batch_actions"]] == [["call-1"], ["call-2"]]


@_in_browser_activity_context
async def test_call_browser_use_with_rotation_rotates_claude_token():
    import domains.spawn_browser_agent_v3.handler as handler
    from domains.spawn_browser_agent_v3.handler import _call_browser_use_with_rotation
    from domains.spawn_browser_agent_v3.types import ClaudeTokenState

    client = _FakeRoseClient(
        [
            {
                "claude_token_error": "rate_limit",
                "rateLimitedUntil": "2026-01-01T00:00:00Z",
            },
            {"actions": [{"type": "done"}]},
        ]
    )
    token_state = ClaudeTokenState()
    token_state.access_token = "old-token"
    token_state.source = "pool"
    token_state.pool_token_id = "pool-old"

    with (
        patch.object(handler.activity, "heartbeat"),
        patch.object(
            handler,
            "report_claude_token_rate_limited",
            new=AsyncMock(),
        ) as mark_limited,
        patch.object(
            handler,
            "fetch_claude_token",
            new=AsyncMock(
                return_value={
                    "accessToken": "new-token",
                    "source": "pool",
                    "poolTokenId": "pool-new",
                }
            ),
        ) as fetch_token,
    ):
        result = await _call_browser_use_with_rotation(
            rose_client=client,
            task="do it",
            dynamic_system_context="dynamic",
            turn_messages=[],
            browser_state={"url": "https://example.com"},
            action_entries=[{"type": "click"}],
            config=_fake_config(),
            user_id="u1",
            agent_id="a1",
            iteration=4,
            token_state=token_state,
            gpt_token=None,
            gpt_account_id=None,
            gpt_token_source=None,
            gpt_token_pool_id=None,
            browser_use_mode="claude",
        )

    assert result == {"actions": [{"type": "done"}]}
    assert len(client.calls) == 2
    assert client.calls[0]["claude_auth"].token == "old-token"
    assert client.calls[1]["claude_auth"].token == "new-token"
    mark_limited.assert_awaited_once()
    fetch_token.assert_awaited_once()
    assert token_state.excluded_pool_ids == ["pool-old"]
    assert token_state.access_token == "new-token"
    assert token_state.pool_token_id == "pool-new"


