async def test_browser_use_oversized_page_fetch_only_blocks_missing_native_download():
    """The size cap gates re-materializing credentialed bytes, never a native download."""
    from domains.spawn_browser_agent_v3.download_persist import (
        _MAX_PERSIST_BYTES,
        persist_navigation_download_via_page_fetch,
    )

    def harness():
        expressions = []

        async def evaluate(*, params, session_id):
            expressions.append(params["expression"])
            if len(expressions) == 1:
                return {
                    "result": {
                        "value": {
                            "ok": True,
                            "size": _MAX_PERSIST_BYTES + 1,
                            "base64": base64.b64encode(b"BIG!").decode(),
                            "filename": "export.zip",
                            "contentType": "application/zip",
                            "disposition": 'attachment; filename="export.zip"',
                        }
                    }
                }
            return {"result": {"value": True}}

        cdp = SimpleNamespace(
            session_id="cdp",
            cdp_client=SimpleNamespace(send=SimpleNamespace(Runtime=SimpleNamespace(evaluate=evaluate))),
        )
        return expressions, SimpleNamespace(get_or_create_cdp_session=AsyncMock(return_value=cdp))

    native = {"path": "/tmp/downloads/export.zip", "size": _MAX_PERSIST_BYTES + 1, "filename": "export.zip"}

    # No native download: the oversized payload must not be pushed back through
    # an in-page blob click, even if that click would have produced a file.
    expressions, session = harness()
    with patch(
        "domains.spawn_browser_agent_v3.download_persist.wait_for_browser_use_download",
        new=AsyncMock(side_effect=[None, native]),
    ) as listing:
        rejected = await persist_navigation_download_via_page_fetch(
            session=session,
            url="https://example.com/export.zip",
            session_id="browser-use-session",
            config=_fake_config(),
            provider="browser-use",
        )
    assert rejected is None
    assert len(expressions) == 1, "oversized payload was re-triggered as a blob download"
    assert listing.await_count == 1

    # Native download present: the size cap must not hide the provider's file.
    expressions, session = harness()
    with patch(
        "domains.spawn_browser_agent_v3.download_persist.wait_for_browser_use_download",
        new=AsyncMock(return_value=native),
    ) as listing:
        kept = await persist_navigation_download_via_page_fetch(
            session=session,
            url="https://example.com/export.zip",
            session_id="browser-use-session",
            config=_fake_config(),
            provider="browser-use",
        )
    assert kept is not None and kept["path"] == native["path"]
    assert kept["content_type"] == "application/zip"
    assert kept["source_url"] == "https://example.com/export.zip"
    assert len(expressions) == 1 and listing.await_count == 1


async def test_download_persister_materializes_one_download_once_under_concurrent_events():
    """A1 (agent 85ec29b8): every download was materialised and uploaded TWICE,
    because Chrome's downloadWillBegin and completed downloadProgress both
    scheduled a materialize and the dedupe key was recorded only after the
    awaits. The key is reserved first (guid-keyed; the completed event may carry
    a different file name), and a failed first attempt still lets the second run."""
    from domains.spawn_browser_agent_v3.download_persist import BrowserDownloadPersister

    cdp_client, browser_session = _make_download_persister_cdp_harness()
    fetches = []
    gate = asyncio.Event()
    outcomes = []

    async def slow_page_fetch(*, session, url, session_id, config, provider=None, trust_download=False):
        fetches.append(url)
        await gate.wait()  # both events arrive while the first fetch is in flight
        outcome = outcomes.pop(0) if outcomes else "ok"
        if outcome == "fail":
            return None
        return {"path": "/tmp/downloads/out.zip", "size": 8, "filename": "out.zip", "mime_type": "application/zip"}

    for first_outcome, expected_fetches in (("ok", 1), ("fail", 2)):
        fetches.clear()
        outcomes[:] = [first_outcome]
        gate.clear()
        # The completed event adds filePath to the shared meta; the provider file
        # read is unavailable here, so both attempts fall through to the page fetch.
        with patch(
            "domains.spawn_browser_agent_v3.repo.download_session_file", new=AsyncMock(return_value=None)
        ), patch(
            "domains.spawn_browser_agent_v3.download_persist.persist_navigation_download_via_page_fetch",
            new=slow_page_fetch,
        ):
            persister = await BrowserDownloadPersister.create(
                browser_session=browser_session,
                session_id="kernel-sess",
                config=_fake_config(),
                provider="kernel",
            )
            assert persister is not None
            handlers = cdp_client.register.Browser.handlers
            handlers["downloadWillBegin"](
                {"guid": f"guid-{first_outcome}", "url": "https://example.com/out.zip", "suggestedFilename": "out.zip"},
                "cdp-sess",
            )
            handlers["downloadProgress"](
                {"guid": f"guid-{first_outcome}", "state": "completed", "filePath": "/tmp/downloads/out (1).zip"},
                "cdp-sess",
            )
            await asyncio.sleep(0.05)
            assert len(fetches) == 1, ("the second event must wait for the attempt in flight", fetches)
            gate.set()
            await asyncio.gather(*list(persister._tasks), return_exceptions=True)
            assert len(fetches) == expected_fetches, (first_outcome, fetches)
            assert [item["name"] for item in persister.downloaded_files()] == ["out.zip"]
            await persister.close()


async def test_materialize_prefers_provider_file_path_before_page_fetch():
    """CDP filePath should be read via provider Files API before page-fetch fallback."""
    from domains.spawn_browser_agent_v3.download_persist import BrowserDownloadPersister

    page_fetch_calls = []
    cdp_client, browser_session = _make_download_persister_cdp_harness()

    async def fake_download(config, session_id, file_path):
        assert file_path == "/tmp/downloads/out.zip"
        return {"content": b"ZIPBYTES", "filename": "out.zip", "mime_type": "application/zip"}

    async def fake_upload(config, session_id, *, filename, content, mime_type, provider=None):
        return {
            "path": f"/tmp/downloads/{filename}",
            "size": len(content),
            "filename": filename,
            "mime_type": mime_type,
        }

    async def fake_page_fetch(*, session, url, session_id, config, provider=None, trust_download=False):
        page_fetch_calls.append(url)
        return None

    with patch(
        "domains.spawn_browser_agent_v3.repo.download_session_file",
        new=fake_download,
    ):
        with patch(
            "domains.spawn_browser_agent_v3.download_persist.persist_bytes_to_session_downloads",
            new=fake_upload,
        ):
            with patch(
                "domains.spawn_browser_agent_v3.download_persist.persist_navigation_download_via_page_fetch",
                new=fake_page_fetch,
            ):
                persister = await BrowserDownloadPersister.create(
                    browser_session=browser_session,
                    session_id="kernel-sess",
                    config=_fake_config(),
                    provider="kernel",
                )
                assert persister is not None
                handlers = cdp_client.register.Browser.handlers
                handlers["downloadWillBegin"](
                    {
                        "guid": "guid-path",
                        "url": "https://example.com/out.zip",
                        "suggestedFilename": "out.zip",
                    },
                    "cdp-sess",
                )
                # Cancel the willBegin-scheduled page-fetch task; we want the
                # completed progress path (with filePath) to drive materialize.
                for task in list(persister._tasks):
                    task.cancel()
                if persister._tasks:
                    await asyncio.gather(*list(persister._tasks), return_exceptions=True)
                persister._tasks.clear()
                persister._persisted_keys.clear()
                handlers["downloadProgress"](
                    {
                        "guid": "guid-path",
                        "state": "completed",
                        "filePath": "/tmp/downloads/out.zip",
                    },
                    "cdp-sess",
                )
                await asyncio.sleep(0)
                if persister._tasks:
                    await asyncio.gather(*list(persister._tasks), return_exceptions=True)
                await persister.close()

    assert page_fetch_calls == [], "provider filePath read must short-circuit page fetch"


