# Response header bag captured verbatim from browser-smoke r002-j0037 (Kernel
# session wgn8hi7g18qtr916omp6y3td, 2026-10-23T02:55:58Z): Kernel's residential
# proxy answered a failed upstream connect with its own 502 page.
_KERNEL_PROXY_ERROR_HEADERS = {
    "cache-control": "no-store",
    "content-length": "9332",
    "content-type": "text/html; charset=utf-8",
    "x-content-type-options": "nosniff",
    "x-kernel-proxy-error": "upstream_connect_failed",
}


def _goto_document_recorder():
    from domains.spawn_browser_agent_v3.recording import BrowserNetworkRecorder

    recorder = BrowserNetworkRecorder(
        browser_session=MagicMock(),
        agent_id="agent",
        task_id="task",
        session_id="session",
        output_dir=Path("/tmp/browser-goto-proxy-test"),
    )
    recorder._network_generation = 1
    return recorder


def _deliver_document(recorder, request_id, url, *, status, headers):
    recorder._on_request_will_be_sent(
        {"requestId": request_id, "type": "Document", "documentURL": url, "request": {"url": url, "method": "GET"}},
        None,
        1,
    )
    recorder._on_response_received(
        {
            "requestId": request_id,
            "type": "Document",
            "response": {"url": url, "status": status, "statusText": "Bad Gateway", "headers": headers},
        },
        None,
        1,
    )


async def _goto_with_document(recorder, *, request_id=None, status=502, headers=None, url="www.roselabs.ai"):
    """Run the model's goto action while the main-frame Document response arrives."""
    from domains.spawn_browser_agent_v3.service_actions import execute_action

    def dispatch(_event):
        if request_id is not None:
            _deliver_document(recorder, request_id, "https://www.roselabs.ai/", status=status, headers=headers)
        return _make_awaitable_event(None)

    dom = MagicMock()
    dom.ensure_browser_overlays_suppressed = AsyncMock()
    dom.session = _fake_session_with_event_bus(dispatch_side_effect=dispatch)
    dom.selector_map = {}
    ah = _mocked_action_history()
    out = await execute_action(
        dom,
        ah,
        {"action": "goto", "params": {"url": url}},
        browser_network_recorder=recorder,
    )
    ah.record_action.assert_awaited_once()
    assert ah.record_action.await_args.kwargs["result"] == out
    return out


async def test_execute_goto_reports_kernel_proxy_error_document():
    """Kernel's own 502 page is a failed navigation; an origin 502 stays a normal load."""
    recorder = _goto_document_recorder()

    out = await _goto_with_document(recorder, request_id="proxy-1", status=502, headers=_KERNEL_PROXY_ERROR_HEADERS)
    assert out["success"] is False, out
    assert out["error"] == (
        "Navigation failed: Kernel's browser proxy could not reach www.roselabs.ai "
        "(upstream_connect_failed) and served its own HTTP 502 page. "
        "The browser's network exit failed, not the site."
    )
    assert out["current_url"] == "https://www.roselabs.ai"

    # The origin's own 502 (no proxy header) is a page the model reads as usual.
    out = await _goto_with_document(
        recorder, request_id="origin-502", status=502, headers={"content-type": "text/html"}
    )
    assert out == {"success": True, "message": "", "current_url": "https://www.roselabs.ai"}

    # A proxy page from an earlier navigation never fails a later goto that
    # produced no new document response (for example a same-document hash change).
    stale = _goto_document_recorder()
    _deliver_document(stale, "old", "https://www.roselabs.ai/", status=502, headers=_KERNEL_PROXY_ERROR_HEADERS)
    out = await _goto_with_document(stale, url="https://www.roselabs.ai/")
    assert out["success"] is True


async def test_live_tab_recovery_keeps_kernel_proxy_error_document():
    """Model-called recovery is not skipped as a clean page on Kernel's proxy-error page."""
    from domains.spawn_browser_agent_v3.challenge_recovery import live_tab_looks_challenged

    class _Page:
        url = "https://www.roselabs.ai/"

    classifier = AsyncMock(return_value={"clean": True})
    with patch(
        "domains.spawn_browser_agent_v3.challenge_llm_classifier.classify_page_after_settle",
        classifier,
    ):
        recorder = _goto_document_recorder()
        _deliver_document(recorder, "proxy", _Page.url, status=502, headers=_KERNEL_PROXY_ERROR_HEADERS)
        assert await live_tab_looks_challenged(_Page(), network_recorder=recorder) is True
        classifier.assert_not_awaited()

        # A later real load of the same page supersedes the proxy page.
        _deliver_document(recorder, "origin", _Page.url, status=200, headers={"content-type": "text/html"})
        assert await live_tab_looks_challenged(_Page(), network_recorder=recorder) is False
        classifier.assert_awaited_once()


async def test_execute_goto_err_aborted_persists_attachment_download():
    """goto net::ERR_ABORTED on a download URL must persist bytes under /tmp/downloads."""
    from domains.spawn_browser_agent_v3 import service_actions

    class _FailEvent:
        def __await__(self):
            async def _done():
                return None

            return _done().__await__()

        async def event_result(self, **_kwargs):
            raise RuntimeError("Navigation failed: net::ERR_ABORTED")

    session = SimpleNamespace(
        event_bus=SimpleNamespace(dispatch=MagicMock(return_value=_FailEvent())),
    )
    ah = _mocked_action_history()
    download_url = "https://tinypng.com/backend/opt/download/abc/rs.jpeg"

    async def fake_persist(**kwargs):
        assert kwargs["url"] == download_url
        assert kwargs["session_id"] == "sess-dl"
        return {
            "path": "/tmp/downloads/rs.jpeg",
            "size": 149852,
            "filename": "rs.jpeg",
            "content_type": "image/jpeg",
            "source_url": download_url,
        }

    with patch(
        "domains.spawn_browser_agent_v3.download_persist.persist_navigation_download_via_page_fetch",
        new=fake_persist,
    ):
        out = await service_actions._execute_goto(
            session=session,
            dom_service=MagicMock(),
            action_history=ah,
            params={"url": download_url},
            thinking=None,
            session_id="sess-dl",
            config=_fake_config(),
        )
    assert out["success"] is True
    assert out["download"]["path"] == "/tmp/downloads/rs.jpeg"
    assert "saved to session" in out["message"]
    ah.record_action.assert_awaited_once()


async def test_execute_action_goto_download_fallback_uses_the_session_provider():
    """CR 4501806264: the ERR_ABORTED goto fallback persisted by the ambient BROWSER_PROVIDER.

    ``_execute_goto`` called the download helper without the session's provider
    or user, so the helper resolved the provider from the BROWSER_PROVIDER env
    (tilion on Fly). A Kernel session's download then landed in the Tilion
    worker ledger instead of its session files, and a Tilion session's download
    skipped the durable attachment copy. The provider and user ride from the
    harness through ``execute_action`` to the persistence helper; the env is
    pinned to the *other* provider so only the session's own value can pass.
    """
    from domains.spawn_browser_agent_v3 import tilion_worker
    from domains.spawn_browser_agent_v3.service_actions import execute_action

    url = "https://files.example.com/export/report.pdf"
    body = b"%PDF-1.4 goto fallback"
    payload = {
        "ok": True,
        "status": 200,
        "size": len(body),
        "contentType": "application/pdf",
        "filename": "report.pdf",
        "base64": base64.b64encode(body).decode(),
        "disposition": 'attachment; filename="report.pdf"',
    }

    class _AbortedNavigation:
        def __await__(self):
            async def _done():
                return None

            return _done().__await__()

        async def event_result(self, **_kwargs):
            raise RuntimeError("Navigation failed: net::ERR_ABORTED")

    def dom_for_aborted_download():
        cdp = SimpleNamespace(
            session_id="cdp",
            cdp_client=SimpleNamespace(
                send=SimpleNamespace(Runtime=SimpleNamespace(evaluate=AsyncMock(return_value={"result": {"value": payload}})))
            ),
        )
        dom = MagicMock()
        dom.selector_map = {}
        dom.ensure_browser_overlays_suppressed = AsyncMock()
        dom.session = SimpleNamespace(
            event_bus=SimpleNamespace(dispatch=MagicMock(return_value=_AbortedNavigation())),
            get_or_create_cdp_session=AsyncMock(return_value=cdp),
        )
        return dom

    async def goto_download(*, env_provider, session_provider, session_id):
        upload = AsyncMock(return_value={"path": "/tmp/downloads/report.pdf", "size": len(body)})
        storage = AsyncMock(return_value={"storage_path": "user-1/report.pdf", "file_name": "report.pdf"})
        with (
            patch.dict(os.environ, {"BROWSER_PROVIDER": env_provider}, clear=False),
            patch("domains.spawn_browser_agent_v3.repo.upload_file_to_session", new=upload),
            patch("helpers.attachments.upload_to_storage", new=storage),
        ):
            out = await execute_action(
                dom_for_aborted_download(),
                _mocked_action_history(),
                {"action": "goto", "params": {"url": url}},
                session_id=session_id,
                config=_fake_config(),
                user_id="user-1",
                provider=session_provider,
            )
        return out, upload, storage

    try:
        # A Kernel session on a tilion-default worker keeps the session-files path.
        out, upload, storage = await goto_download(
            env_provider="tilion", session_provider="kernel", session_id="goto-dl-kernel"
        )
        assert out["success"] is True, out
        assert out["download"]["path"] == "/tmp/downloads/report.pdf"
        upload.assert_awaited_once()
        assert upload.await_args.args[2:4] == ("report.pdf", body)
        storage.assert_not_awaited()
        assert tilion_worker.list_downloads("goto-dl-kernel") == [], "Kernel bytes never enter the Tilion ledger"

        # A Tilion session on a kernel-default worker keeps the durable ledger path.
        out, upload, storage = await goto_download(
            env_provider="kernel", session_provider="tilion", session_id="goto-dl-tilion"
        )
        assert out["success"] is True, out
        upload.assert_not_awaited()
        storage.assert_awaited_once()
        assert storage.await_args.kwargs["user_id"] == "user-1"
        assert [entry["filename"] for entry in tilion_worker.list_downloads("goto-dl-tilion")] == ["report.pdf"]
        assert tilion_worker.download_file_pointer("goto-dl-tilion", out["download"]["path"]) is not None
    finally:
        tilion_worker.release_session("goto-dl-kernel")
        tilion_worker.release_session("goto-dl-tilion")


