async def test_wait_for_navigation_ready_reloads_blank_spa_shell_once():
    from domains.spawn_browser_agent_v3 import service_actions

    class FakePage:
        def __init__(self):
            self.reloads = 0
            self.evaluations = 0

        async def wait_for_load_state(self, *_args, **_kwargs):
            return None

        async def evaluate(self, _code):
            self.evaluations += 1
            if self.reloads == 0:
                return json.dumps(
                    {
                        "hasAppRoot": True,
                        "appRootReady": False,
                        "plainPageReady": False,
                        "bodyTextLength": 677,
                        "rootChildren": 0,
                        "blankSpaShell": True,
                    }
                )
            return {
                "hasAppRoot": True,
                "appRootReady": True,
                "plainPageReady": False,
                "bodyTextLength": 12,
                "rootChildren": 1,
                "blankSpaShell": False,
            }

        async def reload(self):
            self.reloads += 1
            return None

