async def test_terminal_visual_persistence_preserves_control_exceptions():
    import textwrap
    from pathlib import Path
    from types import SimpleNamespace
    from unittest.mock import AsyncMock, patch
    from domains.spawn_browser_agent_v3.handler import BrowserInstructionUnavailableError
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError
    from helpers.workflow_generation import WorkflowGenerationSealed
    text = (Path(__file__).resolve().parents[2] / 'domains/spawn_browser_agent_v3/handler.py').read_text()
    start = text.index('                        from domains.spawn_browser_agent_v3.service_visual_evidence import persist_terminal_visual_evidence')
    stop = text.index('                        await _close_browser_with_cleanup_receipt', start)
    code = 'async def run():\n' + textwrap.indent(textwrap.dedent(text[start:stop]), '    ') + '    return visual_evidence\n'
    env = {'asyncio': asyncio, 'BrowserSessionCloseError': BrowserSessionCloseError,
           'BrowserInstructionUnavailableError': BrowserInstructionUnavailableError,
           'WorkflowGenerationSealed': WorkflowGenerationSealed,
           'action_history': None, 'dom_service': None, 'session_id': 'session', 'task_id': 'task', 'agent_id': 'agent',
           '_redact_activity_value': lambda value: value, 'extract_error_message': str,
           'logger': SimpleNamespace(warning=lambda *args, **kwargs: None)}
    exec(compile(code, __file__, 'exec'), env)
    for error in (asyncio.CancelledError(), WorkflowGenerationSealed(),
                  BrowserSessionCloseError('session', True),
                  BrowserInstructionUnavailableError({'type': 'fixture', 'message': 'fixture'})):
        with patch('domains.spawn_browser_agent_v3.service_visual_evidence.persist_terminal_visual_evidence',
                   AsyncMock(side_effect=error)):
            try:
                await env['run']()
            except BaseException as raised:
                assert raised is error
            else:
                raise AssertionError('terminal evidence swallowed control exception')


async def _run_realm_transition_action_fixture(
    action_name,
    *,
    redirect=True,
    restoration_error=False,
    fatal_error=None,
    minted_password_text=None,
    credential_action=None,
    credential_failure=False,
    credential_origin=None,
    navigation_error=None,
    navigation_stays_on_old_page=False,
    reload_error=None,
    unexpected_worker_state=False,
    reported_cookie_injection=False,
    preparation_states=None,
):
    """Drive real activity/action/history with synthetic CDP and private hydration."""
    from contextlib import ExitStack
    import copy
    from urllib.parse import urlparse
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.credential_runtime import build_realm_credential_state
    from domains.spawn_browser_agent_v3.service import AuthRuntimeState

    old_url = "https://old.example/login"
    final_url = "https://new.example/login"
    requested_url = old_url if redirect else final_url
    preapproved_handoff = action_name == "preapproved_handoff"
    assistance_url = "https://auth.example/login"
    old_secret = "synthetic-prior-realm-password"
    new_secret = "synthetic-current-realm-password"
    shared_ref = "pwd:new" if minted_password_text is not None or credential_action is not None else "pwd:fixture"
    active_page = {"url": final_url if preapproved_handoff else old_url, "title": "Sign in", "dom_tree": "Sign in"}
    events = []
    model_contexts = []
    initial_credentials_ready = asyncio.Event()
    native_register = _FakeDomService.register_secret_refs

    def register_credentials(dom, refs):
        native_register(dom, refs)
        if old_secret in refs.values():
            initial_credentials_ready.set()
    saved = AsyncMock()
    propagated = AsyncMock(return_value={"outcome": "unknown", "refs": 0, "applied": 0})
    session_info = {
        "session_id": "session-1",
        "debug_url": "https://kernel.example/debug",
        "ws_url": "ws://old",
        "passwords": [],
        "auth_options": {"realm": "old.example"},
        "browser_session_metadata": {"provider": "kernel"},
        "same_session_available": True,
    }

    async def hydrate(payload, **_kwargs):
        realm = payload["auth_realm"]
        state = await build_realm_credential_state(
            {"auth_realm": realm, "auth_options": {"realm": realm}},
            decryption_key=None,
        )
        state.password_secret_refs = {shared_ref: old_secret if realm == "old.example" else new_secret}
        if credential_action is not None:
            state.password_secret_refs["pwd:other"] = "synthetic-other-password"
        state.password_origins = {ref: credential_origin or "https://" + realm for ref in state.password_secret_refs}
        state.credential_refs_by_secret_ref = {shared_ref: {"kind": "password", "id": realm + "-password"}}
        state.auth_options = {"realm": realm, "passwords": [{"id": realm + "-password", "ref": shared_ref}]}
        state.auth_options_section = "# Auth Options for " + realm + "\nPassword ref: " + shared_ref
        state.auth_runtime_state = AuthRuntimeState.from_auth_options(state.auth_options)
        return state

    async def prepare(_config, **kwargs):
        realm = urlparse(kwargs["target_url"]).hostname
        events.append(("prepare", realm))
        if kwargs.get("restore_browser_state", True):
            events.append(("restore", realm))
        payload = {"auth_realm": realm, "auth_options": {"realm": realm}, "passwords": [], "passkeys": []}
        if reported_cookie_injection:
            payload["cookies_injected"] = True
        if unexpected_worker_state:
            payload["worker_apply"] = {"provider": "tilion", "cookies": [], "local_storage": []}
        if restoration_error or (preapproved_handoff and realm == "new.example"):
            payload["credential_preparation_error"] = "Browser state injection timed out after 18000ms"
        return payload

    class NavigationEvent:
        def __init__(self, kind):
            self.kind = kind

        def __await__(self):
            async def done():
                return None

            return done().__await__()

        async def event_result(self, **_kwargs):
            error = navigation_error if self.kind == "navigate" else reload_error
            if error is not None:
                raise RuntimeError(error)
            return None

    def dispatch(event):
        if action_name in {"goto", "open_new_tab"} and not any(item[0] == "navigate" for item in events):
            events.append(("navigate", event.url))
            active_page["url"] = old_url if navigation_stays_on_old_page else final_url
            return NavigationEvent("navigate")
        else:
            events.append(("reload", event.url))
            active_page["url"] = event.url
            return NavigationEvent("reload")

    async def evaluate(**_kwargs):
        events.append(("evaluate", _kwargs["params"]["expression"]))
        if credential_failure:
            return {"exceptionDetails": {"text": "Synthetic JavaScript failure"}}
        active_page["url"] = final_url
        return {"result": {"value": {"prior": old_secret, "active": new_secret}}}

    cdp = SimpleNamespace(
        session_id="cdp-fixture",
        cdp_client=SimpleNamespace(send=SimpleNamespace(Runtime=SimpleNamespace(evaluate=evaluate))),
    )

    async def identity(*_args, **_kwargs):
        return {"url": active_page["url"], "title": active_page["title"]}

    async def observe(*_args, **_kwargs):
        return dict(active_page)

    async def unexpected_handoff_action(_context):
        events.append(("unexpected-handoff-action", active_page["url"]))
        active_page["url"] = assistance_url
        return {"success": True, "payment_refs_filled": ["card_number"], "message": "Fields filled"}

    async def model_step(**kwargs):
        if fatal_error is not None or minted_password_text is not None or credential_action is not None:
            await asyncio.wait_for(initial_credentials_ready.wait(), timeout=2)
        else:
            await asyncio.sleep(0)  # Let the already scheduled background work run.
        if fatal_error is not None:
            return {"action": {"action": "evaluate", "params": {"code": "1"}}, "usage": {}}
        model_contexts.append(copy.deepcopy(kwargs))
        events.append(("model", len(model_contexts)))
        action = (
            action_name
            if len(model_contexts) == 1 and not preapproved_handoff
            else "request_user_assistance_for_authentication"
        )
        params = (
            {"code": "(() => window.fixtureReadbackAndNavigate())()"}
            if action == "evaluate"
            else ({"url": requested_url} if action in {"goto", "open_new_tab"} else {})
        )
        if credential_action is not None and len(model_contexts) == 1:
            action = credential_action["action"]
            params = copy.deepcopy(credential_action["params"])
        if action == "input_text" and minted_password_text is not None:
            params = {"text": minted_password_text}
        return {
            "action": {"action": action, "thinking": "Inspect the surviving sign-in page", "params": params},
            "usage": {},
            "mode": "waterfall",
        }

    control_calls = 0

    async def user_control(*_args, **_kwargs):
        nonlocal control_calls
        control_calls += 1
        if fatal_error is not None and control_calls > 1:
            await asyncio.wait_for(initial_credentials_ready.wait(), timeout=2)
            raise fatal_error
        return False

    fake_browser = SimpleNamespace(contexts=[SimpleNamespace(pages=[SimpleNamespace()])], close=AsyncMock())
    fake_playwright = _FakePlaywright(fake_browser)
    prefix = "domains.spawn_browser_agent_v3.handler."
    preparations = []
    original_preparation = handler.AsyncCredentialPreparation

    def capture_preparation(*args, **kwargs):
        instance = original_preparation(*args, **kwargs)
        preparations.append(instance)
        return instance

    targets = [
        patch(prefix + "AsyncCredentialPreparation", capture_preparation),
        patch(prefix + "load_config", return_value=_fake_config()),
        patch(prefix + "activity.heartbeat"),
        patch(prefix + "BrowserAgentRecorder.create", AsyncMock(return_value=None)),
        patch(prefix + "fetch_session_info", AsyncMock(return_value=session_info)),
        patch(prefix + "fetch_recent_otps", AsyncMock(return_value=[])),
        patch(
            prefix + "get_model_pricing_with_fallback",
            AsyncMock(return_value={"input_cents_per_1k": 0, "output_cents_per_1k": 0}),
        ),
        patch(prefix + "build_realm_credential_state", hydrate),
        patch.object(_FakeDomService, "register_secret_refs", register_credentials),
        patch(prefix + "activity_drain_reason", AsyncMock(return_value=None)),
        patch(prefix + "prepare_browser_auth", prepare),
        patch(
            prefix + "apply_tilion_worker_state",
            AsyncMock(side_effect=lambda *_args: events.append(("apply-worker-state", "new.example"))),
        ),
        patch(prefix + "_call_browser_use_with_rotation", model_step),
        patch(
            prefix + "_wait_for_browser_user_control",
            user_control,
        ),
        patch(prefix + "_observe_step_page", observe),
        patch.object(_FakeDomService, "get_page_identity", identity),
        patch.object(_FakeDomService, "get_browser_state", observe),
        patch.object(_FakeDomSession, "event_bus", SimpleNamespace(dispatch=dispatch), create=True),
        patch.object(
            _FakeDomSession, "get_focused_target",
            return_value=SimpleNamespace(target_id="fixture-tab"), create=True,
        ),
        patch.object(_FakeDomSession, "get_or_create_cdp_session", AsyncMock(return_value=cdp), create=True),
        patch(prefix + "wait_for_navigation_ready", AsyncMock()),
        patch("domains.spawn_browser_agent_v3.service_actions.wait_for_navigation_ready", AsyncMock()),
        patch(prefix + "create_user_auth_assistance_request", AsyncMock(return_value={"id": "request-1"})),
        patch(prefix + "extract_session_files", AsyncMock(return_value=[])),
        patch("domains.spawn_browser_agent_v3.service.list_session_files", AsyncMock(return_value=[])),
        patch(
            "helpers.llm.check_progress",
            AsyncMock(side_effect=AssertionError("unexpected live verifier in private fixture")),
        ),
        patch(prefix + "disconnect_browser_after_passkey_capture", AsyncMock()),
        patch(prefix + "propagate_browser_run_credentials", propagated),
        patch(prefix + "close_browser_session", AsyncMock()),
        patch(prefix + "save_browser_action_message", saved),
        patch(prefix + "save_browser_assistant_message", AsyncMock()),
        patch(prefix + "save_browser_credential_ref_message", AsyncMock()),
        patch(prefix + "persist_resume_context", AsyncMock(return_value={})),
        patch("domains.spawn_browser_agent_v3.streaming.stream_assistant_chunk", AsyncMock()),
        patch("domains.spawn_browser_agent_v3.streaming.stream_tool_event", AsyncMock()),
        patch("browser_tools.dom_service.DOMService", _FakeDomService),
        patch("browser_tools.humanizer.BrowserHumanizer", _FakeHumanizer),
        patch("playwright.async_api.async_playwright", return_value=_FakeAsyncPlaywright(fake_playwright)),
        patch(prefix + "live_tab_looks_challenged", AsyncMock(return_value=False)),
    ]
    if preapproved_handoff:
        targets.extend(
            [
                patch(
                    "domains.spawn_browser_agent_v3.service_actions.wait_for_payment_ref_fields",
                    AsyncMock(return_value=True),
                ),
                patch(
                    "domains.spawn_browser_agent_v3.service_actions._execute_interaction_action",
                    unexpected_handoff_action,
                ),
            ]
        )
    if minted_password_text is not None or credential_action is not None:

        async def save_minted(_config, _user_id, url):
            events.append(("save-minted", url))

        async def type_text(_humanizer, text):
            events.append(("type-text", text))
            if credential_failure:
                raise RuntimeError("Synthetic typing failure")

        targets.extend(
            [
                patch.object(_FakeHumanizer, "type_text", type_text, create=True),
                patch.object(_FakeHumanizer, "press_key", AsyncMock(), create=True),
                patch(prefix + "save_minted_account_password", save_minted),
            ]
        )
    with ExitStack() as stack:
        for target in targets:
            stack.enter_context(target)
        pending = handler.spawn_browser_agent_activity_v3(
            user_id="user-1",
            agent_id="agent-1",
            goal="Inspect realm-bound authentication",
            tool_call_id="tool-1",
            task_id="task-1",
            is_resume=True,
            start_url=old_url,
            output_schema={"fields": [{"name": "result", "type": "string"}]},
            use_claude_mode=False,
            write_lock_resume_state={
                "approval_type": "manual_pause",
                "task_id": "task-1",
                **(
                    {
                        "payment_card_refs": {
                            "card_number": "4242424242424242",
                            "card_name": "Synthetic Fixture",
                            "card_expiry": "12/30",
                            "card_cvv": "123",
                        }
                    }
                    if preapproved_handoff
                    else {}
                ),
            },
        )
        if fatal_error is not None:
            with pytest.raises(Exception) as caught:
                await pending
            return {
                "error": caught.value,
                "classifier_calls": propagated.await_args_list,
                "saved_calls": saved.await_args_list,
                "contexts": model_contexts,
                "private_state": _FakeDomService.last_instance.secret_redaction_state(),
            }
        result = await pending
    if preparation_states is not None:
        preparation_states.extend(copy.deepcopy(p.state) for p in preparations)
    assert result["status"] == "awaiting_auth_assistance"
    assert len(model_contexts) == (1 if preapproved_handoff else 2), "redirect reload added a model call"
    if preapproved_handoff:
        assert result["auth_realm"] == "new.example", "a harness-initiated payment action changed the active realm"
    return model_contexts, saved, events, old_secret, new_secret


@_in_browser_activity_context
async def test_activity_saves_minted_password_after_canonical_or_legacy_entry():
    """The actual activity saves a successfully entered advertised password ref."""
    for text in ("{{secret:pwd:new}}", "pwd:new"):
        contexts, _saved, events, prior, active = await _run_realm_transition_action_fixture(
            "input_text",
            minted_password_text=text,
        )
        assert events.count(("save-minted", "https://old.example/login")) == 1, (
            "successful minted password entry did not persist the account password"
        )
        assert ("type-text", prior) in events, "input_text bypassed private resolution"
        assert prior not in str(contexts) and active not in str(contexts)

    cases = [
        (
            {
                "action": "evaluate",
                "params": {"code": "document.querySelector('#password').value = '{{secret:pwd:new}}'"},
            },
            True,
            False,
            None,
        ),
        (
            {"action": "goto", "params": {"url": "https://old.example/signup?password={{secret:pwd:new}}"}},
            True,
            False,
            None,
        ),
        ({"action": "input_text", "params": {"text": "ordinary text"}}, False, False, None),
        ({"action": "input_text", "params": {"text": "{{secret:pwd:other}}"}}, False, False, None),
        ({"action": "input_text", "params": {"text": "{{secret:pwd:missing}}"}}, False, False, None),
        ({"action": "evaluate", "params": {"code": "/* {{secret:pwd:new}} */ 'ordinary text'"}}, False, False, None),
        ({"action": "evaluate", "params": {"code": "'{{secret:pwd:missing}}'"}}, False, False, None),
        (
            {
                "action": "evaluate",
                "params": {"code": "document.querySelector('#password').value = '{{secret:pwd:new}}'"},
            },
            False,
            True,
            None,
        ),
        ({"action": "input_text", "params": {"text": "{{secret:pwd:new}}"}}, False, True, None),
        ({"action": "evaluate", "params": {"code": "'{{secret:pwd:new}}'"}}, False, False, "https://unrelated.example"),
    ]
    for action, should_save, failure, origin in cases:
        contexts, _saved, events, prior, active = await _run_realm_transition_action_fixture(
            action["action"],
            credential_action=action,
            credential_failure=failure,
            credential_origin=origin,
        )
        consumed = [value for kind, value in events if kind in {"type-text", "evaluate", "navigate"}]
        if should_save or failure:
            assert any(prior in value for value in consumed), "action bypassed private resolution"
        if origin:
            assert not consumed, "password origin denial reached browser execution"
        if action["params"].get("text") == "{{secret:pwd:other}}":
            assert ("type-text", "synthetic-other-password") in events
        save_calls = [event for event in events if event[0] == "save-minted"]
        assert save_calls == ([("save-minted", "https://old.example/login")] if should_save else []), (
            f"minted password persistence mismatch: action={action['action']}, "
            f"should_save={should_save}, failure={failure}, denied={bool(origin)}, saves={save_calls}"
        )
        assert "synthetic-other-password" not in str(contexts)
        assert prior not in str(contexts) and active not in str(contexts)


@_in_browser_activity_context
async def test_activity_fatal_error_keeps_credentials_out_of_classifier_and_temporal_failure():
    """Exercise the real activity fatal boundary after its private password hydration."""
    from temporalio.api.failure.v1 import Failure
    from temporalio.converter import DefaultFailureConverter, DefaultPayloadConverter
    from temporalio.exceptions import ApplicationError

    secret = "synthetic-prior-realm-password"
    raw = ApplicationError(
        "provider returned " + secret, {"echo": secret}, type="SyntheticProviderFailure", non_retryable=True
    )
    raw.__cause__ = RuntimeError("private cause: " + secret)
    captured = await _run_realm_transition_action_fixture("evaluate", fatal_error=raw)
    assert secret in captured["private_state"]["secret_redaction_refs"].values(), (
        "fatal fixture did not reach private credential hydration"
    )
    assert not captured["contexts"], "fatal fixture unexpectedly recorded a normal actor decision"
    assert captured["classifier_calls"], "fatal fixture did not exercise actual credential propagation"
    assert secret not in str(captured["classifier_calls"]), (
        "the fatal activity sent a raw password into the credential classifier"
    )
    assert secret not in str(captured["saved_calls"]), (
        "the fatal activity persisted a raw password in its completion message"
    )
    failure = Failure()
    DefaultFailureConverter().to_failure(captured["error"], DefaultPayloadConverter(), failure)
    assert secret.encode() not in failure.SerializeToString(), (
        "the activity's fatal error leaked through Temporal into its parent agent"
    )
    assert isinstance(captured["error"], ApplicationError)
    assert captured["error"].type == "SyntheticProviderFailure"
    assert captured["error"].non_retryable is True


@_in_browser_activity_context
async def test_activity_cross_realm_action_redacts_reused_ref_values():
    """Activation reusing a ref must not erase prior-secret masking coverage."""
    import json

    contexts, saved, events, prior, active = await _run_realm_transition_action_fixture("evaluate")
    tools = [message for message in contexts[1]["turn_messages"] if message["role"] == "tool"]
    assert len(tools) == 1 and tools[0]["name"] == "evaluate"
    result = json.loads(tools[0]["content"])
    assert result["auth_context"]["auth_realm"] == "new.example"
    assert result["value"]["prior"] != prior, "cross-realm activation leaked the prior password into model history"
    assert result["value"]["active"] != active, "cross-realm activation leaked the newly activated password"
    assert prior not in tools[0]["content"] and active not in tools[0]["content"]
    persisted = [call.kwargs for call in saved.await_args_list if call.kwargs.get("action_type") == "evaluate"]
    assert persisted and any("Executed JS" in call.get("message", "") for call in persisted)
    assert all(prior not in str(call) and active not in str(call) for call in persisted), (
        "persisted action result leaked a realm password"
    )
    assert ("prepare", "new.example") in events, "test did not activate a different private credential realm"


def _assert_nonblocking_navigation_context(contexts, events, *, realm, success, error=None):
    from urllib.parse import urlsplit
    assert len(contexts) == 2
    assert sum(kind == "navigate" for kind, _ in events) == 1, "navigation was repeated"
    assert events.count(("model", 2)) == 1, "actor missed the navigation result"
    assert not any(kind == "reload" for kind, _ in events), "credential work forced a navigation reload"
    assert events.index(next(event for event in events if event[0] == "navigate")) < events.index(("model", 2))
    tools = [message for message in contexts[1]["turn_messages"] if message["role"] == "tool"]
    result = json.loads(tools[0]["content"])
    assert result["success"] is success
    assert urlsplit(result["current_url"]).hostname == realm, "result URL and current credential realm diverged"
    if error is not None:
        assert error in result["error"]
    auth = result["auth_context"]
    assert auth["auth_realm"] == realm
    assert auth["credential_preparation_status"] in {"pending", "ready", "error"}
    assert "synthetic-prior-realm-password" not in str(contexts)
    assert "synthetic-current-realm-password" not in str(contexts)
    return auth




