async def test_approval_parking_captures_before_installed_sdk_stop():
    from browser_approval_lifecycle_support import ApprovalLifecycleProbe
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    for provider in ("browser-use", "kernel"):
        for scenario in ("write", "payment", "auth"):
            probe = ApprovalLifecycleProbe(provider, "ok", scenario)
            await test_private_browser_pause_urls_use_protected_continuity(probe)
        for failure in ("checkpoint_failure", "passkey_failure", "recorder_failure"):
            probe = ApprovalLifecycleProbe(provider, failure, "write")
            expected = RuntimeError if failure == "recorder_failure" else BrowserSessionCloseError
            with pytest.raises(expected):
                await test_private_browser_pause_urls_use_protected_continuity(probe)
            await handler.drain_background_browser_cleanups(timeout=2)
            assert probe.alive and "backend_release" not in probe.events and "sdk_provider_stop" not in probe.events, probe.events
            assert "recording_finalized" in probe.events, probe.events
            assert "reset_cdp" in probe.events, "failure must exercise actual detach and finalizer"
            if failure == "checkpoint_failure":
                assert "checkpoint" in probe.events
            elif failure == "passkey_failure":
                assert "passkey_capture" in probe.events and "checkpoint" not in probe.events
            else:
                assert "replay_stop" in probe.events and "checkpoint" not in probe.events


async def test_approval_parking_verifies_real_passkey_capture():
    from browser_approval_lifecycle_support import RealPasskeyCaptureProbe
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    failures = []
    for provider in ("browser-use", "kernel"):
        for mode in ("acquire_failure", "command_failure", "missing_credential", "save_failure", "save_exception", "cancel_read"):
            probe = RealPasskeyCaptureProbe(provider, mode, "write")
            try:
                with pytest.raises(BrowserSessionCloseError):
                    await test_private_browser_pause_urls_use_protected_continuity(probe)
                await handler.drain_background_browser_cleanups(timeout=2)
                assert probe.alive and "backend_release" not in probe.events, probe.events
                assert "recording_finalized" in probe.events and "reset_cdp" in probe.events, probe.events
            except BaseException as error:
                if isinstance(error, (KeyboardInterrupt, SystemExit)):
                    raise
                failures.append((provider, mode, type(error).__name__, str(error)))
        for mode in ("used", "unused", "no_passkeys", "unseeded", "invalidated_used"):
            probe = RealPasskeyCaptureProbe(provider, mode, "payment")
            try:
                await test_private_browser_pause_urls_use_protected_continuity(probe)
            except Exception as error:
                failures.append((provider, mode, type(error).__name__, str(error)))
        for mode in ("acquire_failure", "command_failure", "save_failure"):
            probe = RealPasskeyCaptureProbe(provider, mode, "auth")
            try:
                await test_private_browser_pause_urls_use_protected_continuity(probe)
            except Exception as error:
                failures.append((provider, "auth-" + mode, type(error).__name__, str(error)))
    assert not failures, failures


async def test_terminal_passkey_failure_still_pauses_without_weakening_approval():
    from browser_approval_lifecycle_support import TerminalPasskeyCaptureProbe
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    failures = []
    for provider in ("browser-use", "kernel"):
        for mode in ("acquire_failure", "command_failure", "missing_credential", "save_failure", "save_exception", "cancel_read"):
            for scenario in ("completed", "max_steps", "cancelled", "error", "write", "payment", "auth"):
                probe = TerminalPasskeyCaptureProbe(provider, mode, scenario)
                try:
                    if scenario in {"write", "payment"}:
                        with pytest.raises(BrowserSessionCloseError):
                            await test_private_browser_pause_urls_use_protected_continuity(probe)
                        await handler.drain_background_browser_cleanups(timeout=2)
                        assert probe.alive and "checkpoint" not in probe.events and "backend_release" not in probe.events, probe.events
                        assert "recording_finalized" in probe.events and "reset_cdp" in probe.events, probe.events
                    elif scenario == "auth":
                        # Optional parking capture never owns terminal cancellation.
                        # The matrix's cancelled/error cases still exercise required
                        # foreground control flow and assert actual provider cleanup.
                        await test_private_browser_pause_urls_use_protected_continuity(probe)
                        assert probe.result["status"] == "awaiting_auth_assistance", probe.result
                        assert probe.alive and "backend_release" not in probe.events, probe.events
                        assert "checkpoint" not in probe.events and "recording_finalized" in probe.events, probe.events
                        if mode == "save_exception":
                            assert "save_reference" in probe.events, "persistence failure was never exercised"
                            assert probe.result.get("browser_page_observation") is None
                        elif mode == "cancel_read":
                            assert "readback" in probe.events, "read cancellation was never exercised"
                            assert probe.result.get("browser_page_observation") is None
                    else:
                        if scenario == "error":
                            with pytest.raises(RuntimeError, match="fixture terminal model failure"):
                                await test_private_browser_pause_urls_use_protected_continuity(probe)
                        else:
                            await test_private_browser_pause_urls_use_protected_continuity(probe)
                        await probe.assert_terminal_cleanup(handler)
                except BaseException as error:
                    if isinstance(error, (KeyboardInterrupt, SystemExit)):
                        raise
                    failures.append((provider, mode, scenario, type(error).__name__, str(error)))
    assert not failures, failures


async def test_terminal_passkey_error_keeps_fixture_transports_until_cleanup():
    from browser_approval_lifecycle_support import TerminalPasskeyCaptureProbe
    from domains.spawn_browser_agent_v3 import handler

    class PendingRecorderProbe(TerminalPasskeyCaptureProbe):
        def install(self, stack, handler):
            super().install(stack, handler)
            schedule = handler._schedule_browser_cleanup

            def cleanup(**kwargs):
                kwargs["network_recorder_task"] = asyncio.create_task(asyncio.sleep(0.01, result=None))
                return schedule(**kwargs)

            stack.enter_context(patch.object(handler, "_schedule_browser_cleanup", side_effect=cleanup))

    probe = PendingRecorderProbe("browser-use", "command_failure", "error")
    with pytest.raises(RuntimeError, match="fixture terminal model failure"):
        await test_private_browser_pause_urls_use_protected_continuity(probe)
    await probe.assert_terminal_cleanup(handler)


async def test_tilion_terminal_pause_detaches_after_optional_passkey_capture():
    from browser_approval_lifecycle_support import TerminalPasskeyCaptureProbe
    from domains.spawn_browser_agent_v3 import handler

    class TilionTerminalProbe(TerminalPasskeyCaptureProbe):
        session_provider = "tilion"

        async def close(self, config, session_id, **options):
            assert "reset_cdp" in self.events, ("terminal checkpoint still has worker CDP", self.events)
            assert self.alive, self.events
            return await super().close(config, session_id, **options)

    for scenario in ("completed", "max_steps", "cancelled", "error"):
        probe = TilionTerminalProbe("tilion", "missing_credential", scenario)
        if scenario == "error":
            with pytest.raises(RuntimeError, match="fixture terminal model failure"):
                await test_private_browser_pause_urls_use_protected_continuity(probe)
        else:
            await test_private_browser_pause_urls_use_protected_continuity(probe)
        await handler.drain_background_browser_cleanups(timeout=2)
        assert not probe.alive, probe.events
        assert probe.events.count("checkpoint") == probe.events.count("backend_release") == 1
        assert "sdk_provider_stop" not in probe.events and "recording_finalized" in probe.events
        assert "Passkey usage capture incomplete; continuing terminal browser pause" in probe.warnings
        assert probe.events.index("replay_stop") < probe.events.index("checkpoint")
        assert probe.events.index("reset_cdp") < probe.events.index("checkpoint")
        if probe.result is not None:
            assert probe.result["status"] == {"completed": "completed", "max_steps": "max_iterations", "cancelled": "cancelled"}[scenario]
            assert "browser_cleanup" not in probe.result


async def test_tilion_approval_call_sites_transfer_cdp_without_releasing_source():
    from browser_approval_lifecycle_support import ApprovalLifecycleProbe
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    class TilionProbe(ApprovalLifecycleProbe):
        session_provider = "tilion"

        def install(self, stack, handler):
            super().install(stack, handler)
            if self.mode == "detach_false":
                async def failed_detach(_dom):
                    self.events.append("detach_unconfirmed")
                    return False
                stack.enter_context(patch.object(handler, "_disconnect_browser", side_effect=failed_detach))

        async def close(self, config, session_id, **options):
            assert "detach_unconfirmed" not in self.events, self.events
            assert "reset_cdp" in self.events, ("worker still owns CDP", self.events)
            assert self.alive, ("detach must not release the native", self.events)
            return await super().close(config, session_id, **options)

        async def observe(self, result, handler):
            await handler.drain_background_browser_cleanups(timeout=2)
            assert "sdk_provider_stop" not in self.events, self.events
            assert self.events.index("passkey_capture") < self.events.index("replay_stop")
            assert self.events.index("passkey_capture") < self.events.index("reset_cdp")
            assert self.events.index("replay_stop") < self.events.index("checkpoint")
            assert self.events.index("reset_cdp") < self.events.index("checkpoint")
            assert self.events.index("checkpoint") < self.events.index("backend_release")
            assert "recording_finalized" in self.events
            assert not self.alive
            assert result["status"] in {"awaiting_write_approval", "awaiting_payment_card_approval"}, result["status"]

    for scenario in ("write", "payment"):
        probe = TilionProbe("tilion", "ok", scenario)
        await test_private_browser_pause_urls_use_protected_continuity(probe)
        probe = TilionProbe("tilion", "checkpoint_failure", scenario)
        with pytest.raises(BrowserSessionCloseError):
            await test_private_browser_pause_urls_use_protected_continuity(probe)
        await handler.drain_background_browser_cleanups(timeout=2)
        assert probe.alive and "backend_release" not in probe.events, probe.events
        assert "reset_cdp" in probe.events and "recording_finalized" in probe.events
        probe = TilionProbe("tilion", "detach_false", scenario)
        with pytest.raises(BrowserSessionCloseError):
            await test_private_browser_pause_urls_use_protected_continuity(probe)
        await handler.drain_background_browser_cleanups(timeout=2)
        assert probe.alive and "checkpoint" not in probe.events and "backend_release" not in probe.events, probe.events
        assert "detach_unconfirmed" in probe.events and "recording_finalized" in probe.events


async def test_pause_transfers_exclusive_cdp_before_backend_checkpoint():
    """Actual helper: preserve passkeys and fail closed without a proven CDP detach."""
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    tree = ast.parse((AGENTS_ROOT / "domains/spawn_browser_agent_v3/handler.py").read_text())
    helper = next(node for node in ast.walk(tree) if isinstance(node, ast.AsyncFunctionDef)
                  and node.name == "_close_browser_with_cleanup_receipt")
    factory = ast.parse("def factory():\n    cleanup_failure = None\n    dom_service = initial_dom\n").body[0]
    factory.body.append(helper)
    factory.body.extend(ast.parse("return _close_browser_with_cleanup_receipt, lambda: cleanup_failure, lambda: dom_service").body)
    for mode in ("ok", "capture_fail", "capture_optional", "recorder_fail", "detach_false",
                 "detach_error", "detach_cancel", "close_409", "close_500", "close_cancel",
                 "other_session", "not_pause", "no_dom", "kernel", "unknown_provider"):
        events = []
        attached = True
        exact = "other" if mode == "other_session" else "current"
        pause = mode != "not_pause"
        provider = "kernel" if mode == "kernel" else "" if mode == "unknown_provider" else "tilion"
        dom = None if mode == "no_dom" else object()
        transfers = pause and exact == "current" and dom is not None

        async def capture(_callback):
            events.append("capture")
            return mode not in {"capture_fail", "capture_optional"}

        async def stop(_recorder):
            events.append("recorder")
            if mode == "recorder_fail":
                raise RuntimeError("recorder failed")

        async def detach(actual):
            nonlocal attached
            assert actual is dom
            events.append("detach")
            if mode == "detach_false":
                return False
            if mode == "detach_error":
                raise RuntimeError("detach failed")
            if mode == "detach_cancel":
                raise asyncio.CancelledError()
            attached = False
            return True

        async def close(_config, actual, **options):
            assert actual == exact
            assert options == {"pause": pause, "current_url": "https://shop.example/checkout"}
            events.append("checkpoint")
            if transfers:
                assert not attached, "backend checkpoint collided with worker CDP owner"
                assert events.index("capture") < events.index("detach") < events.index("checkpoint")
                assert events.index("capture") < events.index("recorder") < events.index("checkpoint")
            else:
                assert "detach" not in events, "do not detach unrelated/provider-owned sessions"
            if mode in {"close_409", "close_500"}:
                raise BrowserSessionCloseError(actual, pause, int(mode[-3:]))
            if mode == "close_cancel":
                raise asyncio.CancelledError()
            events.append("backend_release")

        namespace = {
            "Dict": dict, "Any": object, "asyncio": asyncio,
            "BrowserSessionCloseError": BrowserSessionCloseError,
            "session_id": "current", "initial_dom": dom,
            "browser_session_metadata": {"provider": provider},
            "_capture_browser_passkey_usage": capture, "record_passkey_usage_once": AsyncMock(),
            "_stop_kernel_replay_before_session_close": stop, "browser_recorder": object(),
            "_disconnect_browser": detach, "_tilion_leave_session": lambda: events.append("bank"), "close_browser_session": close, "config": object(),
            "credential_signin_realms": set(), "task_id": "task",
            "world_state_receipt_summary": lambda _receipt: [],
            "logger": SimpleNamespace(info=lambda *a, **kw: None, warning=lambda *a, **kw: None),
        }
        exec(compile(ast.fix_missing_locations(ast.Module(body=[factory], type_ignores=[])),
                     "actual-tilion-pause-helper", "exec"), namespace)
        call, receipt, current_dom = namespace["factory"]()
        if mode in {"recorder_fail", "detach_error"}:
            with pytest.raises(RuntimeError):
                await call(exact, pause=pause, current_url="https://shop.example/checkout", require_complete_passkeys=True)
        elif mode in {"detach_cancel", "close_cancel"}:
            with pytest.raises(asyncio.CancelledError):
                await call(exact, pause=pause, current_url="https://shop.example/checkout", require_complete_passkeys=True)
        else:
            await call(exact, pause=pause, current_url="https://shop.example/checkout",
                       require_complete_passkeys=mode != "capture_optional")
        if mode in {"capture_fail", "recorder_fail", "detach_false", "detach_error", "detach_cancel"}:
            assert "checkpoint" not in events and "backend_release" not in events, (mode, events)
        if mode in {"close_409", "close_500", "close_cancel"}:
            assert "checkpoint" in events and "backend_release" not in events
        failed = mode in {"capture_fail", "recorder_fail", "detach_false", "detach_error", "detach_cancel",
                          "close_409", "close_500", "close_cancel"}
        assert (receipt() is not None) == failed, (mode, receipt(), events)
        if mode in {"close_409", "close_500"}:
            assert receipt()["http_status"] == int(mode[-3:])
        if not failed:
            assert "backend_release" in events
        if transfers and mode not in {"capture_fail", "detach_false", "detach_error", "detach_cancel"}:
            assert current_dom() is None and events.count("bank") == 1, (mode, events)
        if mode == "recorder_fail":
            assert "checkpoint" not in events and "detach" in events
        if mode in {"capture_fail", "detach_false", "detach_error", "detach_cancel"}:
            assert current_dom() is dom and "bank" not in events


async def test_approval_pause_checkpoint_failures_do_not_acknowledge_parking():
    """Run the actual nested close/park helpers, including failed HTTP and cancellation."""
    from domains.spawn_browser_agent_v3.repo import BrowserSessionCloseError

    source = ast.parse((AGENTS_ROOT / "domains/spawn_browser_agent_v3/handler.py").read_text())
    helpers = [
        node for node in ast.walk(source)
        if isinstance(node, ast.AsyncFunctionDef)
        and node.name == "_close_browser_with_cleanup_receipt"
    ]
    assert len(helpers) == 1, "all parking must use the existing close/checkpoint boundary"
    factory = ast.parse("def factory():\n    cleanup_failure = None\n    dom_service = object()\n").body[0]
    factory.body.extend(helpers)
    factory.body.extend(ast.parse('async def pause():\n    await _close_browser_with_cleanup_receipt(session_id, pause=True, current_url=current_url)\n    if cleanup_failure is not None:\n        raise BrowserSessionCloseError(session_id, True, cleanup_failure.get("http_status"))\nreturn pause').body)
    for failure in (None, 500, 409, "cancelled", "disconnect"):
        calls = []

        async def disconnect(_service):
            calls.append("disconnect")
            return failure != "disconnect"

        async def close(config, session_id, **kwargs):
            calls.append((session_id, kwargs))
            if failure == "cancelled":
                raise asyncio.CancelledError()
            if failure is not None:
                raise BrowserSessionCloseError(session_id, True, failure)

        namespace = {
            "asyncio": asyncio, "Dict": dict, "Any": object,
            "BrowserSessionCloseError": BrowserSessionCloseError,
            "close_browser_session": close,
            "_stop_kernel_replay_before_session_close": AsyncMock(),
            "browser_recorder": None, "config": object(),
            "session_id": "ephemeral-checkout", "current_url": "https://shop.example/checkout",
            "credential_signin_realms": set(), "task_id": "task",
            "world_state_receipt_summary": lambda receipt: [],
            "logger": SimpleNamespace(info=lambda *args, **kwargs: None),
            "_capture_browser_passkey_usage": AsyncMock(return_value=True),
            "record_passkey_usage_once": AsyncMock(),
            "dom_service": object(),
            "browser_session_metadata": {},
            "_disconnect_browser": disconnect,
            "_tilion_leave_session": lambda: calls.append("banked"),
        }
        exec(compile(ast.fix_missing_locations(ast.Module(body=[factory], type_ignores=[])), "approval-parking-helpers", "exec"), namespace)
        pause = namespace["factory"]()
        if failure == "cancelled":
            with pytest.raises(asyncio.CancelledError):
                await pause()
        elif failure is not None:
            with pytest.raises(BrowserSessionCloseError):
                await pause()
        else:
            await pause()
        if failure == "disconnect":
            assert calls == ["disconnect"], "failed CDP detach must not request a checkpoint"
        else:
            assert calls == [
                "disconnect", "banked",
                ("ephemeral-checkout", {"pause": True, "current_url": "https://shop.example/checkout"}),
            ]


async def test_private_browser_pause_urls_use_protected_continuity(_lifecycle_probe=None):

    """Activity results expose redacted URLs while exact continuation stays private."""
    from contextlib import ExitStack
    from temporalio.testing import ActivityEnvironment
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.config import BROWSER_DRAIN_YIELD_STATUS
    from helpers.activity_generation_drain import WORKER_SHUTDOWN

    secret = "synthetic-private-url-password"
    realm = secret + ".fixture.test"
    start_url = "https://" + realm + "/"
    raw_url = getattr(_lifecycle_probe, "merchant_url", None) or start_url + "checkout?password=" + secret
    visible_url = raw_url.replace(secret, "{{secret:pwd:url}}")
    output_schema = {"fields": [{"name": "result", "type": "string", "description": raw_url, "minLength": 234}]}
    screenshot = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGOY234XAAPGAgJSNphuAAAAAElFTkSuQmCC"
    trusted_ref = {"kind": "password", "id": "fixture-234-credential", "label": secret}

    def validate_transport_images(value):
        if isinstance(value, dict):
            for item in value.values():
                validate_transport_images(item)
        elif isinstance(value, list):
            for item in value:
                validate_transport_images(item)
        elif isinstance(value, str) and value.startswith("data:image/png;base64,"):
            decoded = base64.b64decode(value.split(",", 1)[1], validate=True)
            assert decoded.startswith(b"\x89PNG\r\n\x1a\n"), "non-PNG raster reached model transport"

    # Ordinary image attachments keep vision when no private value changes
    # their bytes or envelope, including the extra-user-message transport.
    from browser_tools.dom_service import DOMService
    from domains.spawn_browser_agent_v3.types import ClaudeTokenState

    ordinary_image = {"type": "image_url", "image_url": {"url": "data:image/png;base64," + screenshot}}
    ordinary_messages = [
        {
            "role": "user",
            "content": [
                {"type": "text", "text": "Inspect this ordinary image."},
                copy.deepcopy(ordinary_image),
            ],
        }
    ]
    no_secret_client = _FakeRoseClient([{"actions": []}])
    await handler._call_browser_use_with_rotation(
        rose_client=no_secret_client,
        task="Inspect image",
        dynamic_system_context="",
        turn_messages=copy.deepcopy(ordinary_messages),
        browser_state={},
        action_entries=[],
        extra_user_messages=copy.deepcopy(ordinary_messages),
        config=_fake_config(),
        user_id="u1",
        agent_id="a1",
        iteration=1,
        token_state=ClaudeTokenState(),
        gpt_token=None,
        gpt_account_id=None,
        gpt_token_source=None,
        gpt_token_pool_id=None,
        browser_use_mode=None,
        dom_service=DOMService("ws://unused-no-private-image-fixture"),
    )
    ordinary_call = no_secret_client.calls[0]
    validate_transport_images(ordinary_call)
    assert ordinary_call["turn_messages"][0]["content"][1] == ordinary_image, "no-secret attachment lost vision"
    assert ordinary_call["browser_state"]["_extra_user_messages"][0]["content"][1] == ordinary_image
    failures = []
    for scenario in (_lifecycle_probe.scenarios if _lifecycle_probe else (
        "actor_before",
        "actor_after",
        "drain",
        "write",
        "payment",
        "payment_alias",
        "auth",
        "completed",
        "max_steps",
        "declined",
        "raster_completed",
        "raster_max_steps",
    )):
        actor_resume = scenario.startswith("actor_")
        pause = (
            "payment"
            if scenario == "payment_alias"
            else ("drain" if actor_resume else scenario.removeprefix("raster_"))
        )
        private_entry = scenario != "actor_before" and not scenario.startswith("raster_")
        prior_messages = []
        if actor_resume:
            handler._append_browser_turn_messages(
                prior_messages,
                unified_action={"action": "screenshot", "params": {}},
                result={"success": True, "screenshot": screenshot},
                tool_call_id="capture-234",
            )
            prior_messages.append(
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": secret},
                        {"type": "image_url", "image_url": {"url": "data:image/png;base64," + screenshot}},
                    ],
                }
            )
            handler._append_browser_turn_messages(
                prior_messages,
                unified_action={"action": "click", "index": 234, "params": {"label": secret}},
                result={"success": True, "value": {"index": 234, "role": "user", "function": secret}},
                tool_call_id="click-234",
            )
        env = ActivityEnvironment()
        snapshots = []
        route_calls = []
        grants = []
        approval_close = AsyncMock(side_effect=_lifecycle_probe.close if _lifecycle_probe else None)
        resuming = False
        archive_ref = {"paths": ["private-fixture-234"], "sha256": "fixture234"}
        auth_response = {
            "id": "request-234",
            "current_url": raw_url,
            "request": {
                "id": "request-234",
                "browserSessionId": "task-234",
                "steelSessionId": "session-234",
                "authRealm": realm,
                "mode": "live_view",
            },
            "handoff": {
                "type": "live_view",
                "steelSessionId": "session-234",
                "liveViewUrl": "https://kernel.fixture/view/session-234",
            },
        }
        auth_request = AsyncMock(return_value=auth_response)
        private_target = {"index": 234, "attrs": {"href": raw_url, "value": secret}}

        class PrivateURLDom(_FakeDomService):
            async def connect(self):
                if _lifecycle_probe:
                    remote = await _lifecycle_probe.connect(self.cdp_url)
                    self.disconnect = remote.disconnect
                    if getattr(_lifecycle_probe, "capture_real_passkeys", False):
                        self.get_used_passkey_credential_ids = remote.get_used_passkey_credential_ids

            def runtime_current_url(self, *, fallback=""):
                return raw_url

            async def get_page_identity(self):
                return self.model_visible_value({"url": raw_url, "title": "Checkout"})

            async def get_browser_state(self, include_screenshot=False):
                state = self.model_visible_value(
                    {"url": raw_url, "title": "Checkout", "dom_tree": "Checkout " + secret}
                )
                if include_screenshot:
                    state["screenshot"] = screenshot
                return state

        async def persist(**kwargs):
            validate_transport_images(kwargs["state"])
            snapshots.append(copy.deepcopy(kwargs))
            return {"browser_resume_context_ref": copy.deepcopy(archive_ref)}

        async def execute(*_args, **kwargs):
            if _lifecycle_probe:
                _lifecycle_probe.parking = True
            route_calls.append(kwargs["current_url"])
            grants.append(copy.deepcopy(kwargs["write_lock_approvals"]))
            if pause in {"drain", "max_steps"} or resuming:
                if pause != "max_steps":
                    env.worker_shutdown()
                return {"success": True, "current_url": raw_url, "credential_ref": trusted_ref, "message": secret}
            if pause == "write":
                return {"status": "needs_write_approval", "approval_type": "purchase", "question": raw_url}
            return {
                "status": "needs_payment_card_approval",
                "payment_request": {
                    "url": raw_url,
                    "merchant": "Fixture Merchant",
                    "currency": "USD",
                    "subtotal_cents": 1350,
                    "total_cents": 1960,
                    "fees": [{"label": "Tax", "amount_cents": 111}, {"label": "Shipping", "amount_cents": 499}],
                    ("lineItems" if scenario == "payment_alias" else "line_items"): [
                        {
                            "name": "Canvas Tote",
                            "image_url": "https://public.fixture/tote.png",
                            "product_url": raw_url,
                            "rating": "4.7 stars",
                            "review_count": "212 reviews",
                            "unit_price_cents": 450,
                            "quantity": 1,
                            "line_total_cents": 450,
                            "note": secret,
                            "screenshot": "data:image/png;base64," + screenshot,
                        },
                        {
                            "name": "Secret URL",
                            "image_url": raw_url,
                            "product_url": raw_url,
                            "rating": "4.7 stars",
                            "review_count": "212 reviews",
                            "unit_price_cents": 450,
                            "quantity": 1,
                            "line_total_cents": 450,
                        },
                        {
                            "name": "Raster",
                            "image_url": "data:image/png;base64," + screenshot,
                            "product_url": raw_url,
                            "rating": "4.7 stars",
                            "review_count": "212 reviews",
                            "unit_price_cents": 450,
                            "quantity": 1,
                            "line_total_cents": 450,
                        },
                    ],
                },
            }

        action = (
            "request_user_assistance_for_authentication"
            if pause == "auth"
            else "request_payment_card"
            if pause == "payment"
            else "attempt_completion"
            if pause in {"completed", "declined"}
            else "scroll"
        )
        session_info = {
            "session_id": "session-1",
            "ws_url": "ws://fixture",
            "debug_url": "https://kernel.fixture/view",
            "same_session_available": True,
            "auth_options": {"realm": realm},
            "browser_session_metadata": {"provider": getattr(_lifecycle_probe, "session_provider", "kernel")},
            "passwords": [],
        }
        fake_browser = SimpleNamespace(contexts=[SimpleNamespace(pages=[SimpleNamespace()])], close=AsyncMock())
        prefix = "domains.spawn_browser_agent_v3.handler."
        native_start = await native_browser_start_source("1970-01-01T00:00:00+00:00")
        save_action = AsyncMock()

        async def actor_transport(**kwargs):
            validate_transport_images(kwargs)
            return {"action": {"action": action, "coordinates": {"x": 234, "y": 234}, "params": {}}, "usage": {}}

        actor_client = AsyncMock(side_effect=actor_transport)
        judge = AsyncMock(return_value={"score": 1.0, "task_completed": True, "structured_response": {"url": raw_url}, "usage": {}})
        verifier_prompt_builder = MagicMock(wraps=handler.build_verifier_prompt)
        screenshot_upload = AsyncMock(
            return_value={
                "id": "fixture-final-screenshot",
                "storage_path": "fixtures/screenshot_final.png",
                "original_filename": "screenshot_final.png",
                "mime_type": "image/png",
                "size_bytes": len(base64.b64decode(screenshot, validate=True)),
                "created_at": "2026-10-16T00:00:00+00:00",
            }
        )
        from domains.spawn_browser_agent_v3 import service as browser_service

        async def verifier_context(**kwargs):
            context = await browser_service.build_browser_verifier_context(**kwargs)
            context.insert(
                0,
                {
                    "role": "USER",
                    "text": secret,
                    "content": [
                        {"type": "image_url", "image_url": {"url": "data:image/png;base64," + screenshot}},
                    ],
                },
            )
            return context

        patches = [
            patch(prefix + "poll_new_messages", AsyncMock(return_value=[native_start])),
            patch(prefix + "load_config", return_value=getattr(_lifecycle_probe, "config", None) or _fake_config()),
            patch(
                prefix + "fetch_session_info",
                AsyncMock(side_effect=lambda *_args, **_kwargs: copy.deepcopy(session_info)),
            ),
            patch(prefix + "fetch_recent_otps", AsyncMock(return_value=[])),
            patch(
                prefix + "get_model_pricing_with_fallback",
                AsyncMock(return_value={"input_cents_per_1k": 0, "output_cents_per_1k": 0}),
            ),
            patch(prefix + "BrowserAgentRecorder.create", AsyncMock(return_value=None)),
            patch(
                prefix + "_call_browser_use_with_rotation",
                handler._call_browser_use_with_rotation
                if actor_resume
                else AsyncMock(
                    return_value={
                        "action": {"action": action, "coordinates": {"x": 234, "y": 234}, "params": {}},
                        "usage": {},
                        "_fast_cache_browser_target": private_target,
                    }
                ),
            ),
            patch(prefix + "BrowserStreamingRoseClient.complete_browser_use", actor_client),
            patch(prefix + "execute_action", execute),
            patch(
                prefix + "_generate_write_lock_notification",
                AsyncMock(return_value={"question": raw_url, "notification": {"service": {"url": raw_url}}}),
            ),
            patch(prefix + "create_user_auth_assistance_request", auth_request),
            patch(prefix + "_wait_for_browser_user_control", AsyncMock(return_value=False)),
            patch(prefix + "extract_session_files", AsyncMock(return_value=[])),
            patch(prefix + "disconnect_browser_after_passkey_capture", AsyncMock()),
            patch(
                prefix + "propagate_browser_run_credentials",
                AsyncMock(return_value={"outcome": "unknown", "refs": 0, "applied": 0}),
            ),
            patch(prefix + "close_browser_session", approval_close),
            patch(prefix + "save_browser_action_message", save_action),
            patch(prefix + "save_browser_assistant_message", AsyncMock()),
            patch(prefix + "persist_resume_context", persist),
            patch("domains.spawn_browser_agent_v3.streaming.stream_assistant_chunk", AsyncMock()),
            patch("domains.spawn_browser_agent_v3.streaming.stream_tool_event", AsyncMock()),
            patch("browser_tools.dom_service.DOMService", getattr(_lifecycle_probe, "dom_factory", PrivateURLDom)),
            patch("browser_tools.humanizer.BrowserHumanizer", _FakeHumanizer),
            patch(
                "playwright.async_api.async_playwright",
                return_value=_FakeAsyncPlaywright(_FakePlaywright(fake_browser)),
            ),
            patch(prefix + "live_tab_looks_challenged", AsyncMock(return_value=False)),
            patch(prefix + "build_browser_verifier_context", verifier_context),
            patch("domains.spawn_browser_agent_v3.service.list_session_files", AsyncMock(return_value=[])),
            patch(prefix + "call_temporal_activity_from_activity", judge),
            patch(prefix + "build_verifier_prompt", verifier_prompt_builder),
            patch(prefix + "upload_to_storage", screenshot_upload),
        ]
        resume_state = {
            "approval_type": handler.AUTH_ASSISTANCE_DECLINED if pause == "declined" else "manual_pause",
            **({"session_id": "session-1"} if pause == "declined" else {}),
            "secret_redaction_refs": {
                "pwd:url": secret,
                "card_cvv": "234",
                "pwd:image-token": "image_url",
                "pwd:content-token": "content",
                "pwd:metadata-token": "metadata",
                "pwd:user-token": "user",
                "pwd:assistant-token": "assistant",
                "pwd:tool-token": "tool",
                "pwd:function-token": "function",
                "pwd:name-token": "name",
                "pwd:upper-user-token": "USER",
                "pwd:upper-tool-token": "TOOL",
            },
            "secret_values_used": private_entry,
            "browser_turn_messages": copy.deepcopy(prior_messages),
        }
        if getattr(_lifecycle_probe, "resume_state", None):
            resume_state = copy.deepcopy(_lifecycle_probe.resume_state)
        if pause == "declined":
            handler._append_browser_turn_messages(
                resume_state["browser_turn_messages"],
                unified_action={"action": "request_user_assistance_for_authentication", "params": {}},
                result={"success": True, "request_id": "denied-auth-234"},
                tool_call_id="denied-auth-call-234",
            )
            resume_state["rejected_action"] = {
                "tool_call_id": "denied-auth-call-234", "approval_type": "auth_assistance",
                "request_id": "denied-auth-234", "url": raw_url,
            }
        if pause == "max_steps":
            # Exercise the native terminal branch with a single fixture step.
            patches.append(patch(prefix + "MAX_ITERATIONS", 1))
            private_resume = {
                **copy.deepcopy(resume_state),
                "private_browser_runtime": {"browser_output_schema": copy.deepcopy(output_schema)},
            }
            patches.append(patch(prefix + "hydrate_resume_context", AsyncMock(return_value=private_resume)))
            resume_state = {"approval_type": "manual_pause", "browser_resume_context_ref": archive_ref}
        with ExitStack() as stack:
            for item in patches:
                stack.enter_context(item)
            if _lifecycle_probe:
                _lifecycle_probe.install(stack, handler)
            try:
                result = await env.run(
                    handler.spawn_browser_agent_activity_v3,
                    user_id="u1",
                    agent_id="a1",
                    goal="Inspect checkout",
                    tool_call_id="tool-1",
                    task_id="task-1",
                    is_resume=True,
                    use_claude_mode=False,
                    output_schema={"fields": [{**output_schema["fields"][0], "description": visible_url}]}
                    if pause == "max_steps"
                    else copy.deepcopy(output_schema),
                    start_url=start_url,
                    write_lock_resume_state=resume_state,
                )
            finally:
                if _lifecycle_probe:
                    # Remote transport fakes own the entire async cleanup lifetime,
                    # including activity exceptions that bypass observe().
                    await handler.drain_background_browser_cleanups(timeout=2)
            if _lifecycle_probe:
                await _lifecycle_probe.observe(result, handler)
                return
            if pause in {"write", "payment"}:
                approval_close.assert_awaited_once_with(
                    _fake_config(), "session-1", pause=True, current_url=raw_url
                )
            elif pause == "auth":
                approval_close.assert_not_awaited()
            if pause == "write" and snapshots[-1]["state"].get("private_browser_runtime"):
                protected = snapshots[-1]["state"]["private_browser_runtime"]
                assert protected["current_url"] == raw_url
                assert protected["auth_realm"] == realm
                assert protected["grant_url"] == raw_url
                assert protected["pending_action_target"] == private_target
                assert protected["browser_output_schema"] == output_schema
                assert snapshots[-1]["state"]["browser_output_schema"]["fields"][0] == {
                    **output_schema["fields"][0],
                    "description": visible_url,
                }
                assert result["pending_action_target"]["index"] == 234
                # The manager transports only the opaque archive reference and
                # the user's decision timestamp, never the exact private URL.
                public_resume = {
                    "approval_type": "purchase",
                    "write_lock_approved_at": 123.0,
                    "pending_action": {"action": "scroll", "params": {}},
                    "pending_action_target": result["pending_action_target"],
                    "session_id": "session-1",
                    "task_id": "task-1",
                    "step_count": 1,
                    "write_lock_approvals": {"purchase": {"domain": "masked.invalid", "approved_at": 123.0}},
                    "browser_resume_context_ref": result["browser_resume_context_ref"],
                }
                assert secret not in str(public_resume)
                private_resume = {**copy.deepcopy(snapshots[-1]["state"]), **public_resume}
                stack.enter_context(patch(prefix + "hydrate_resume_context", AsyncMock(return_value=private_resume)))
                env = ActivityEnvironment()
                resuming = True
                resumed = await env.run(
                    handler.spawn_browser_agent_activity_v3,
                    user_id="u1",
                    agent_id="a1",
                    goal="Inspect checkout",
                    tool_call_id="tool-1",
                    task_id="task-1",
                    is_resume=True,
                    use_claude_mode=False,
                    output_schema=copy.deepcopy(output_schema),
                    start_url="https://masked.invalid/",
                    write_lock_resume_state=public_resume,
                )
                assert resumed["status"] == BROWSER_DRAIN_YIELD_STATUS
                assert secret not in str(resumed)
                assert grants[-1]["purchase"] == {"domain": realm, "approved_at": 123.0}
                assert grants[-1]["site"]["domain"] == "fixture.test"
                assert route_calls[-1] == raw_url
                # The approved site permission survives private hydration and new input.
                correction = {
                    "id": "correction-234",
                    "role": "USER",
                    "text": "Keep the existing checkout permission and inspect the page.",
                    "timestamp": "1970-01-01T00:00:01+00:00",
                }
                stack.enter_context(
                    patch(prefix + "poll_new_messages", AsyncMock(return_value=[native_start, correction]))
                )
                generator = stack.enter_context(
                    patch(
                        "helpers.llm._generate_response_schema_with_rose",
                        AsyncMock(return_value=(copy.deepcopy(output_schema), None, {})),
                    )
                )
                env = ActivityEnvironment()
                corrected = await env.run(
                    handler.spawn_browser_agent_activity_v3,
                    user_id="u1",
                    agent_id="a1",
                    goal="Inspect checkout",
                    tool_call_id="tool-1",
                    task_id="task-1",
                    is_resume=True,
                    use_claude_mode=False,
                    output_schema=copy.deepcopy(output_schema),
                    start_url="https://masked.invalid/",
                    write_lock_resume_state=public_resume,
                )
                assert corrected["status"] == BROWSER_DRAIN_YIELD_STATUS
                assert secret not in str(corrected)
                assert grants[-1]["purchase"] == {"domain": realm, "approved_at": 123.0}
                assert snapshots[-1]["state"]["user_instruction_message_ids"] == ["correction-234"]
                assert snapshots[-1]["state"]["schema_user_instruction_count"] == 1
                assert snapshots[-1]["state"]["delivered_user_instruction_count"] == 1
                schema_prompt = generator.await_args.args[0]
                assert secret not in schema_prompt
                visible_schema = json.loads(
                    schema_prompt.split(
                        "Current output schema (preserve fields unless later user feedback changes them):\n", 1
                    )[1].split("\n\n", 1)[0]
                )
                assert visible_schema["fields"][0] == {**output_schema["fields"][0], "description": visible_url}
        expected = {
            "drain": BROWSER_DRAIN_YIELD_STATUS,
            "write": "awaiting_write_approval",
            "payment": "awaiting_payment_card_approval",
            "auth": "awaiting_auth_assistance",
            "completed": "completed",
            "max_steps": "max_iterations",
            "declined": "auth_assistance_declined",
        }[pause]
        assert result["status"] == expected
        if pause == "payment":
            items_key = "lineItems" if scenario == "payment_alias" else "line_items"
            items = result["payment_request"][items_key]
            assert items[0].get("image_url") == "https://public.fixture/tote.png", (
                "typed receipt URL lost at owning activity return"
            )
            assert items[1].get("image_url") == visible_url, "receipt URL leaked private credential"
            assert items[0]["product_url"] == visible_url and items[0]["note"] == "{{secret:pwd:url}}"
            # These are scalar receipt fields, not typed captured-image transport.
            # Keep their ordinary secret redaction while preserving actual image blocks below.
            redacted_receipt_raster = _FakeDomService.last_instance.model_visible_value(
                "data:image/png;base64," + screenshot
            )
            assert items[0]["screenshot"] == redacted_receipt_raster
            assert "image_url" not in items[2], "receipt URL schema admitted a data URI"
        if pause == "completed":
            screenshot_upload.assert_awaited_once_with(
                user_id="u1",
                file_content=base64.b64decode(screenshot, validate=True),
                filename="screenshot_final.png",
                mime_type="image/png",
            )
        else:
            screenshot_upload.assert_not_awaited()
        if actor_resume:
            assert actor_client.await_count == 1, "resumed actor did not reach the actual model boundary"
            actor_history = actor_client.await_args.kwargs["turn_messages"]
            durable_history = snapshots[-1]["state"]["browser_turn_messages"]
            for messages in (actor_history, durable_history):
                validate_transport_images(messages)
                assert secret not in str(messages)
                assert [message["role"] for message in messages[:6]] == [
                    "assistant",
                    "tool",
                    "user",
                    "user",
                    "assistant",
                    "tool",
                ], "native transcript roles were credential-masked"
                call = messages[4]["tool_calls"][0]
                assert call["id"] == "click-234" and call["type"] == "function"
                assert call["function"]["name"] == "click"
                assert json.loads(call["function"]["arguments"]) == {
                    "index": 234,
                    "label": "{{secret:pwd:url}}",
                }
                assert messages[5]["name"] == "click" and messages[5]["tool_call_id"] == "click-234"
                assert json.loads(messages[5]["content"])["value"] == {
                    "index": "{{secret:card_cvv}}",
                    "role": "{{secret:pwd:user-token}}",
                    "{{secret:pwd:function-token}}": "{{secret:pwd:url}}",
                }, "page-controlled protocol-looking values bypassed redaction"
                actual_url = messages[2]["content"][1]["image_url"]["url"]
                assert actual_url == "data:image/png;base64," + screenshot, "resumed screenshot transport was text-masked"
                assert base64.b64decode(actual_url.split(",", 1)[1], validate=True) == base64.b64decode(screenshot)
                assert messages[3]["content"][1]["image_url"]["url"] == actual_url
        if pause in {"drain", "max_steps"}:
            action_saves = [call.kwargs for call in save_action.await_args_list
                            if "coordinates" in (call.kwargs.get("auxiliary") or {})]
            assert action_saves
            for saved in action_saves:
                assert saved["auxiliary"]["coordinates"] == {"x": 234, "y": 234}
            finished = [saved for saved in action_saves if saved.get("extra_metadata")]
            assert finished and finished[-1]["extra_metadata"]["credential_ref"] == {
                **trusted_ref,
                "label": "{{secret:pwd:url}}",
            }
            assert finished[-1]["message"] == "{{secret:pwd:url}}"
        if pause == "declined":
            judge.assert_not_awaited()
            assert result["user_declined_auth"] is True
        if pause in {"completed", "max_steps"}:
            assert judge.await_count == 1
            verifier_args = judge.await_args.kwargs["args"]
            assert verifier_args[5] == ("verifier_browser_max_steps" if pause == "max_steps" else "verifier_browser")
            verifier_prompt_builder.assert_called_once()
            prompt_schema = verifier_prompt_builder.call_args.kwargs["response_schema"]
            expected_schema = {"fields": [{**output_schema["fields"][0], "description": visible_url}]}
            for boundary, schema in (("prompt-builder", prompt_schema), ("check-progress", verifier_args[3])):
                if schema != expected_schema:
                    failures.append(scenario + "-" + boundary + "-unredacted-schema")
            if secret in verifier_args[1]:
                failures.append(scenario + "-rendered-verifier-prompt-secret")
            if pause == "max_steps":
                if prompt_schema is not verifier_args[3]:
                    failures.append(scenario + "-verifier-schema-not-shared")
                assert private_resume["private_browser_runtime"]["browser_output_schema"] == output_schema
            context = judge.await_args.kwargs["args"][0]
            validate_transport_images(context)
            assert context[0]["role"] == "USER" and context[-1]["role"] == "TOOL"
            final_frame = context[-1]["metadata"]
            assert final_frame["screenshot_b64"] == screenshot, "final verifier raster was text-masked"
            assert context[0]["content"][0]["image_url"]["url"] == "data:image/png;base64," + screenshot
            assert secret not in str(context)
        if pause in {"completed", "max_steps"}:
            assert result["browser_output_schema"]["fields"][0] == {
                **output_schema["fields"][0],
                "description": visible_url,
            }
        if secret in str(result):
            failures.append(pause)
        if pause == "auth" and secret in str(auth_request.await_args.kwargs):
            failures.append("auth-request-metadata")
        if pause == "auth":
            visible_auth = result["auth_assistance_request"]
            assert result["request_id"] == visible_auth["id"] == visible_auth["request"]["id"] == "request-234"
            assert visible_auth["request"]["browserSessionId"] == "task-234"
            assert visible_auth["request"]["steelSessionId"] == "session-234"
            assert visible_auth["handoff"] == auth_response["handoff"]
        if pause not in {"auth", "completed", "max_steps", "declined"}:
            assert result["current_url"] in (raw_url, visible_url)
            assert route_calls and all(url == raw_url for url in route_calls), (
                "public URL redaction changed private action routing"
            )
        if pause not in {"completed", "max_steps", "declined"}:
            assert result["browser_resume_context_ref"] == archive_ref, (
                "redaction corrupted a trusted archive reference"
            )
            assert result["session_id"] == "session-1" and result["task_id"] == "task-1"
            assert snapshots and snapshots[-1]["force_private"] is True
            if not snapshots[-1]["state"].get("private_browser_runtime"):
                failures.append(pause + "-missing-private-continuation")
    assert not failures, f"credential-bearing URL escaped activity pause boundary: {failures}"


async def _resume_drained_browser_task_on_reused_session(ttl_ms, on_step, *, activity_budget=None, activity_elapsed=None, resume_state=None, replacement=None, extra_patches=()):
    """Run a drained task resumed at step 3 on the live Steel session the backend let it reuse."""
    import dataclasses
    from contextlib import ExitStack

    from temporalio.testing import ActivityEnvironment
    from temporalio import activity
    from helpers import activity_generation_drain

    from domains.spawn_browser_agent_v3.config import BROWSER_DRAIN_YIELD_STATUS
    from domains.spawn_browser_agent_v3.handler import spawn_browser_agent_activity_v3

    env = ActivityEnvironment()
    if activity_budget is not None:
        env.info = dataclasses.replace(
            env.info,
            start_to_close_timeout=activity_budget,
            started_time=datetime.now(timezone.utc) - (activity_elapsed or timedelta(0)),
        )
    fake_browser = SimpleNamespace(contexts=[SimpleNamespace(pages=[SimpleNamespace()])], close=AsyncMock())
    session_info = {
        "task_id": "task-1",
        "session_id": "session-1",
        "debug_url": "https://steel.example/debug",
        "ws_url": "ws://live",
        "fingerprint_injection": None,
        "passwords": [],
        "auth_options": {"realm": "example.com"},
        "browser_session_metadata": {"provider": "steel", "profile_id": "profile-1"},
        "user_settings": {},
        "same_session_available": True,
        "browser_session_health": {"provider": "steel", "sessionId": "session-1", "status": "live", "ttlMs": ttl_ms},
    }
    llm_step = AsyncMock(
        return_value={
            "action": {"action": "scroll", "thinking": "Looking for the cart", "params": {"direction": "down"}},
            "usage": {"prompt_tokens": 900, "completion_tokens": 60, "actual_model": "rose-1-browser-use"},
            "mode": "waterfall",
        }
    )

    async def execute_step(*args, **kwargs):
        await on_step(env)
        return {"success": True, "message": "Scrolled down", "current_url": "https://example.com/cart"}

    native_start = await native_browser_start_source("1970-01-01T00:00:00+00:00")
    resume_mock = AsyncMock()
    if replacement is not None:
        session_info["same_session_available"] = False
        session_info["same_session_unavailable_reason"] = "db_status_paused"
        resume_mock = AsyncMock(return_value={**session_info, "same_session_available": True, **replacement})
    close_mock = AsyncMock()
    save_action_mock = AsyncMock()
    env.save_action_mock = save_action_mock
    # A step may end the provider session: drop the CDP client and the backend's offer.
    fake_playwright = _FakePlaywright(fake_browser)
    env.fake_browser, env.fake_playwright, env.session_info = fake_browser, fake_playwright, session_info
    async def fixture_queue_pointer(**_kwargs):
        return {"task_queue": activity.info().task_queue, "surface_hash": None}

    patch_targets = [
        # Session lifetime is independent of another fixture's worker generation.
        patch.object(activity_generation_drain, "_cached_at", None),
        patch.object(activity_generation_drain, "_cached_queue", None),
        patch.object(activity_generation_drain, "read_agent_queue_pointer", fixture_queue_pointer),
        patch("domains.spawn_browser_agent_v3.handler.poll_new_messages", AsyncMock(return_value=[native_start])),
        patch("domains.spawn_browser_agent_v3.handler.load_config", return_value=_fake_config()),
        patch("domains.spawn_browser_agent_v3.handler.fetch_session_info", AsyncMock(return_value=session_info)),
        patch("domains.spawn_browser_agent_v3.handler.resume_browser_session", resume_mock),
        patch("domains.spawn_browser_agent_v3.handler.fetch_recent_otps", AsyncMock(return_value=[])),
        patch(
            "domains.spawn_browser_agent_v3.handler.get_model_pricing_with_fallback",
            AsyncMock(return_value={"input_cents_per_1k": 0, "output_cents_per_1k": 0}),
        ),
        patch("domains.spawn_browser_agent_v3.handler._call_browser_use_with_rotation", llm_step),
        patch("domains.spawn_browser_agent_v3.handler.execute_action", side_effect=execute_step),
        patch("domains.spawn_browser_agent_v3.handler.build_browser_verifier_context", AsyncMock(return_value=[])),
        patch("domains.spawn_browser_agent_v3.handler.extract_session_files", AsyncMock(return_value=[])),
        patch("domains.spawn_browser_agent_v3.handler.disconnect_browser_after_passkey_capture", AsyncMock()),
        patch(
            "domains.spawn_browser_agent_v3.handler.propagate_browser_run_credentials",
            AsyncMock(return_value={"outcome": "unknown", "refs": 0, "applied": 0}),
        ),
        patch("domains.spawn_browser_agent_v3.handler.close_browser_session", close_mock),
        patch("domains.spawn_browser_agent_v3.handler.save_browser_action_message", save_action_mock),
        patch("domains.spawn_browser_agent_v3.handler.save_browser_assistant_message", AsyncMock()),
        patch("browser_tools.dom_service.DOMService", _FakeDomService),
        patch("browser_tools.humanizer.BrowserHumanizer", _FakeHumanizer),
        patch(
            "playwright.async_api.async_playwright", return_value=_FakeAsyncPlaywright(fake_playwright)
        ),
        patch("domains.spawn_browser_agent_v3.handler.live_tab_looks_challenged", AsyncMock(return_value=False)),
        *extra_patches,
    ]

    with ExitStack() as stack:
        for patch_target in patch_targets:
            stack.enter_context(patch_target)
        result = await env.run(
            spawn_browser_agent_activity_v3,
            user_id="user-1",
            agent_id="agent-1",
            goal="Add the socks to the cart",
            tool_call_id="tool-1",
            task_id="task-1",
            session_id="session-1",
            cdp_url="ws://live",
            is_resume=True,
            output_schema={"fields": [{"name": "result", "type": "string"}]},
            use_claude_mode=False,
            start_url="https://example.com",
            write_lock_resume_state={
                "approval_type": BROWSER_DRAIN_YIELD_STATUS,
                "pending_action": None,
                "write_lock_approvals": {},
                "step_count": 3,
                "session_id": "session-1",
                "cdp_url": "ws://live",
                "task_id": "task-1",
                "auth_realm": "example.com",
                **(resume_state or {}),
            },
        )
    return result, llm_step, resume_mock, close_mock


async def test_browser_task_on_reused_session_yields_before_the_provider_releases_it():
    """A resumed task must leave a reused Steel session before its lifetime runs out.

    Steel releases a session at its absolute lifetime even with CDP attached.
    A resumed or retried activity gets a fresh time budget but may reattach a
    session created by an earlier invocation. Prod agent 3efa7cae lost CDP
    mid-run when the session it was driving expired. The step loop must
    checkpoint while the session still outlives one more step plus teardown,
    so the manager restarts the task on a replacement session.
    """
    from domains.spawn_browser_agent_v3.config import (
        BROWSER_DRAIN_YIELD_STATUS,
        BROWSER_RECORDING_FINALIZE_TIMEOUT_SECONDS,
        BROWSER_SESSION_EXPIRING,
        BROWSER_SESSION_MIN_REMAINING_SECONDS,
        BROWSER_SUPERVISOR_STEP_TIMEOUT_SECONDS,
        BROWSER_DISCONNECT_TIMEOUT_SECONDS,
    )

    assert BROWSER_SESSION_MIN_REMAINING_SECONDS >= (
        BROWSER_SUPERVISOR_STEP_TIMEOUT_SECONDS
        + BROWSER_RECORDING_FINALIZE_TIMEOUT_SECONDS
        + BROWSER_DISCONNECT_TIMEOUT_SECONDS
    ), "a reused session must outlive one supervised step plus teardown"

    async def step_takes_time(env):
        await asyncio.sleep(0.2)

    result, llm_step, resume_mock, close_mock = await _resume_drained_browser_task_on_reused_session(
        BROWSER_SESSION_MIN_REMAINING_SECONDS * 1000 + 100, step_takes_time
    )

    assert llm_step.await_count == 1, (
        f"the task must not start a step the session may not outlive; it ran {llm_step.await_count} steps"
    )
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == BROWSER_SESSION_EXPIRING, result
    assert result["step_count"] == 4, result
    assert result["session_id"] == "session-1" and result["task_id"] == "task-1", result
    assert result["current_url"] == "https://example.com/cart", result
    resume_mock.assert_not_awaited()
    close_mock.assert_not_awaited()


async def test_browser_task_yields_for_a_replacement_when_the_provider_ends_its_session():
    """A provider-ended session must restart the same browser task, not fail the tool call.

    Smoke browser-auth-account-locked (agent ebc611d7, 2026-11-11): Tilion closed
    the CDP socket (code 1012, connect 410 shutdown) during a wait action. The
    next step reattached to the dead native, raised TargetClosedError, and the
    ERROR result made the planner spawn a second browser agent. The step loop
    must instead yield at the boundary so the manager resumes the same task on
    a replacement session. A disconnected client whose session the backend still
    offers keeps stepping (negative control).
    """
    from domains.spawn_browser_agent_v3.config import (
        BROWSER_DRAIN_YIELD_STATUS,
        BROWSER_PROVIDER_SESSION_LOST,
        BROWSER_SESSION_MIN_REMAINING_SECONDS,
    )
    from helpers.activity_generation_drain import WORKER_SHUTDOWN

    ttl_ms = (BROWSER_SESSION_MIN_REMAINING_SECONDS + 600) * 1000

    async def provider_ends_the_session(env):
        env.fake_browser.is_connected = lambda: False
        env.session_info["same_session_available"] = False
        env.session_info["same_session_unavailable_reason"] = "db_status_paused"

    result, llm_step, resume_mock, close_mock = await _resume_drained_browser_task_on_reused_session(
        ttl_ms, provider_ends_the_session
    )
    assert llm_step.await_count == 1, f"stepped on an ended provider session: {llm_step.await_count}"
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == BROWSER_PROVIDER_SESSION_LOST, result
    assert result["step_count"] == 4 and result["task_id"] == "task-1", result
    assert result["session_id"] == "session-1", result
    resume_mock.assert_not_awaited()
    close_mock.assert_not_awaited()

    steps = []

    async def client_drops_but_session_stays_live(env):
        steps.append(1)
        if len(steps) == 1:
            env.fake_browser.is_connected = lambda: False

            async def reattach(*_args, **_kwargs):
                env.fake_browser.is_connected = lambda: True
                return env.fake_browser

            env.fake_playwright.chromium.connect_over_cdp.side_effect = reattach
        if len(steps) == 2:
            env.worker_shutdown()

    result, llm_step, _resume, _close = await _resume_drained_browser_task_on_reused_session(
        ttl_ms, client_drops_but_session_stays_live
    )
    assert llm_step.await_count == 2, "a live offered session must keep serving steps"
    assert result["yield_reason"] == WORKER_SHUTDOWN, result


async def test_browser_task_recovers_only_confirmed_provider_ends_within_budget():
    """Unknown health and an exhausted recovery budget never yield for a replacement.

    The backend's resume refuses a source whose end is unknown, and a provider
    that keeps ending sessions must fail the task instead of allocating one
    replacement per step. A resume that did restore after a provider end tells
    the user the browser was replaced rather than implying continuity.
    """
    from domains.spawn_browser_agent_v3.config import (
        BROWSER_DRAIN_YIELD_STATUS,
        BROWSER_PROVIDER_SESSION_LOST,
        BROWSER_PROVIDER_SESSION_MAX_RECOVERIES,
        BROWSER_SESSION_MIN_REMAINING_SECONDS,
    )

    ttl_ms = (BROWSER_SESSION_MIN_REMAINING_SECONDS + 600) * 1000

    def provider_drop(reason, ended):
        async def drop(env):
            env.fake_browser.is_connected = lambda: False
            env.session_info["same_session_available"] = False
            env.session_info["same_session_unavailable_reason"] = reason
            env.session_info["provider_session_ended"] = ended

        return drop

    # Unknown health keeps the ordinary reattach (which fails here), and a confirmed
    # end with the budget spent fails the task instead of re-allocating.
    for drop, resume_state in (
        (provider_drop("browser_health_check_failed", False), None),
        (
            provider_drop("db_status_paused", True),
            {"provider_session_recoveries": BROWSER_PROVIDER_SESSION_MAX_RECOVERIES},
        ),
    ):
        try:
            await _resume_drained_browser_task_on_reused_session(ttl_ms, drop, resume_state=resume_state)
        except RuntimeError as error:
            assert "Playwright client disconnected" in str(error), error
        else:
            raise AssertionError(f"yielded instead of failing for {resume_state}")

    # Within budget the yield carries the incremented count to the next invocation.
    result, _llm, _resume, _close = await _resume_drained_browser_task_on_reused_session(
        ttl_ms, provider_drop("db_status_paused", True), resume_state={"provider_session_recoveries": 1}
    )
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == BROWSER_PROVIDER_SESSION_LOST, result
    assert result["provider_session_recoveries"] == 2, result

    # The restarted task resumes on the replacement and reports the lost state.
    async def step(env):
        env.worker_shutdown()

    holder = {}

    async def capture(env):
        holder["env"] = env
        await step(env)

    result, _llm, resume_mock, _close = await _resume_drained_browser_task_on_reused_session(
        ttl_ms,
        capture,
        resume_state={"provider_session_recoveries": 1},
        replacement={"session_id": "session-2", "provider_session_lost": {"restored_checkpoint_revision": 0}},
    )
    resume_mock.assert_awaited_once()
    notices = [
        call.kwargs
        for call in holder["env"].save_action_mock.await_args_list
        if (call.kwargs.get("extra_metadata") or {}).get("supervisor_reason") == BROWSER_PROVIDER_SESSION_LOST
    ]
    assert len(notices) == 1, holder["env"].save_action_mock.await_args_list
    assert notices[0]["title"] == "Browser session replaced", notices[0]
    assert notices[0]["extra_metadata"]["restored_checkpoint_revision"] == 0, notices[0]
    assert result["session_id"] == "session-2", result


async def test_browser_provider_session_recovery_covers_first_step_snapshot_and_checkpointed_restore():
    """CodeRabbit PR #2065 follow-ups on the provider-ended recovery.

    The provider can end the session before an invocation's first step; the
    spent budget must live in the shared pause snapshot so no pause path resets
    it; and a restore from an older checkpoint (which the backend cannot prove
    lost once task-info paused the row) is still reported after this task's own
    provider-lost yield, while an ordinary drain resume reports nothing.
    """
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.config import (
        BROWSER_DRAIN_YIELD_STATUS,
        BROWSER_PROVIDER_SESSION_LOST,
        BROWSER_SESSION_MIN_REMAINING_SECONDS,
    )

    ttl_ms = (BROWSER_SESSION_MIN_REMAINING_SECONDS + 600) * 1000
    snapshots = []
    real_persist = handler.persist_resume_context

    async def capture_snapshot(**kwargs):
        snapshots.append(kwargs["state"])
        return await real_persist(**kwargs)

    async def never_steps(env):
        raise AssertionError("an ended provider session must not be stepped")

    result, llm_step, resume_mock, _close = await _resume_drained_browser_task_on_reused_session(
        ttl_ms,
        never_steps,
        resume_state={"provider_session_recoveries": 1},
        extra_patches=(
            patch.object(handler, "_provider_lost_browser_session", AsyncMock(return_value=True)),
            patch.object(handler, "persist_resume_context", capture_snapshot),
        ),
    )
    assert llm_step.await_count == 0, "the first boundary of an invocation is checked too"
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == BROWSER_PROVIDER_SESSION_LOST, result
    assert result["step_count"] == 3 and result["provider_session_recoveries"] == 2, result
    assert snapshots and snapshots[-1]["provider_session_recoveries"] == 2, "every pause snapshot keeps the budget"
    resumed = handler._drain_resume_state(result, None)
    assert resumed["provider_session_recoveries"] == 2, resumed
    assert resumed["resumed_after_provider_session_lost"] is True, resumed
    resume_mock.assert_not_awaited()

    async def stop(env):
        env.worker_shutdown()

    for resume_state, expected_notices in (
        ({"resumed_after_provider_session_lost": True, "provider_session_recoveries": 1}, 1),
        ({}, 0),
    ):
        holder = {}

        async def capture(env):
            holder["env"] = env
            await stop(env)

        result, _llm, resume_mock, _close = await _resume_drained_browser_task_on_reused_session(
            ttl_ms, capture, resume_state=resume_state, replacement={"session_id": "session-2"}
        )
        resume_mock.assert_awaited_once()
        notices = [
            call.kwargs
            for call in holder["env"].save_action_mock.await_args_list
            if (call.kwargs.get("extra_metadata") or {}).get("supervisor_reason") == BROWSER_PROVIDER_SESSION_LOST
        ]
        assert len(notices) == expected_notices, (resume_state, notices)
        assert result["session_id"] == "session-2", result


async def test_browser_task_keeps_stepping_on_a_reused_session_with_time_left():
    """Session lifetime alone must not interrupt a task whose session outlives the next step."""
    from domains.spawn_browser_agent_v3.config import BROWSER_DRAIN_YIELD_STATUS, BROWSER_SESSION_MIN_REMAINING_SECONDS
    from helpers.activity_generation_drain import WORKER_SHUTDOWN

    steps = []

    async def deploy_lands_on_the_second_step(env):
        steps.append(len(steps) + 1)
        if len(steps) == 2:
            env.worker_shutdown()

    result, llm_step, resume_mock, close_mock = await _resume_drained_browser_task_on_reused_session(
        (BROWSER_SESSION_MIN_REMAINING_SECONDS + 600) * 1000, deploy_lands_on_the_second_step
    )

    assert llm_step.await_count == 2, "a session with time left must keep serving steps"
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == WORKER_SHUTDOWN, result
    assert result["step_count"] == 5, result
    resume_mock.assert_not_awaited()
    close_mock.assert_not_awaited()


async def test_browser_task_checkpoints_before_its_activity_start_to_close():
    """A long, healthy task must checkpoint before its own StartToClose kills it.

    Prod agent 0b54f65d (2026-11-13): a phone-setup browser task made 127 steady
    steps (123 successful phone actions, last at 09:19:45) and was hard-killed
    by the 30-minute StartToClose at 09:20:48 mid-step, returning no result. The
    step loop already yields for deploy drain and session expiry; it must yield
    the same way while one more supervised step plus teardown still fits in the
    attempt, so the manager restarts the same task at the same step count.
    """
    from domains.spawn_browser_agent_v3.config import (
        ACTIVITY_START_TO_CLOSE_TIMEOUT_MINUTES,
        BROWSER_ACTIVITY_DEADLINE,
        BROWSER_DRAIN_YIELD_STATUS,
        BROWSER_SESSION_MIN_REMAINING_SECONDS,
    )

    budget = timedelta(minutes=ACTIVITY_START_TO_CLOSE_TIMEOUT_MINUTES)
    assert budget.total_seconds() >= 2 * BROWSER_SESSION_MIN_REMAINING_SECONDS

    async def step(env):
        await asyncio.sleep(0)

    result, llm_step, resume_mock, close_mock = await _resume_drained_browser_task_on_reused_session(
        24 * 3600 * 1000,
        step,
        activity_budget=budget,
        activity_elapsed=budget - timedelta(seconds=BROWSER_SESSION_MIN_REMAINING_SECONDS),
    )
    assert llm_step.await_count == 1, f"started a step the activity may not outlive: {llm_step.await_count}"
    assert result["status"] == BROWSER_DRAIN_YIELD_STATUS, result
    assert result["yield_reason"] == BROWSER_ACTIVITY_DEADLINE, result
    assert result["step_count"] == 4 and result["task_id"] == "task-1", result
    close_mock.assert_not_awaited()

    # Control: the same budget with time left keeps stepping until a real drain.
    steps = []

    async def deploy_lands_on_the_second_step(env):
        steps.append(1)
        if len(steps) == 2:
            env.worker_shutdown()

    result, llm_step, _resume, _close = await _resume_drained_browser_task_on_reused_session(
        24 * 3600 * 1000, deploy_lands_on_the_second_step, activity_budget=budget, activity_elapsed=timedelta(0)
    )
    assert llm_step.await_count == 2, "an attempt with time left must keep serving steps"
    assert result["yield_reason"] != BROWSER_ACTIVITY_DEADLINE, result

    # The 3m Fast Mode demo ceiling stays a hard ceiling (no yield loop).
    from temporalio.testing import ActivityEnvironment
    from domains.spawn_browser_agent_v3.handler import _activity_deadline_near

    short = timedelta(minutes=3)
    env = ActivityEnvironment()
    env.info = dataclasses.replace(env.info, start_to_close_timeout=short, started_time=datetime.now(timezone.utc) - short)
    assert env.run(_activity_deadline_near) is False


