async def test_manager_preserves_business_outcome_and_cleanup_receipt():
    """Actual manager events preserve resource failure separately from business outcome."""
    from domains.spawn_browser_agent_v3.handler import SpawnBrowserAgentManagerV3
    from tools.base import MessageStatus

    receipt = {"status": "failed", "session_id": "session-1", "error": "owned close HTTP 500"}
    for scenario in ("success", "refusal", "cancelled"):
        for failed in (False, True):
            result = {
                "status": "cancelled" if scenario == "cancelled" else "completed",
                "success": scenario == "success",
                "message": "Verified goal" if scenario == "success" else "User declined sign-in",
                "task_id": "task-1",
                "session_id": "session-1",
            }
            if scenario == "refusal":
                result["user_declined_auth"] = True
            if failed:
                result["browser_cleanup"] = receipt

            class Handle:
                def done(self):
                    return True

                def __await__(self):
                    async def returned():
                        return result

                    return returned().__await__()

            instance = SimpleNamespace(
                user_id="user-1", agent_id="agent-1", is_paused=False, write_lock_enabled=True, system_name="Rose"
            )
            with (
                patch(
                    "domains.spawn_browser_agent_v3.handler.workflow.start_activity", return_value=Handle()
                ) as started,
                patch("domains.spawn_browser_agent_v3.handler.workflow.wait_condition", AsyncMock(return_value=None)),
            ):
                events = [
                    event
                    async for event in SpawnBrowserAgentManagerV3().execute_tool(
                        instance, {"goal": "Owned manager fixture"}, "tool-1"
                    )
                ]
            assert started.call_count == 1, "cleanup receipt must not restart business activity"
            final = events[-1]
            serialized = json.loads(json.dumps(final.to_dict()))
            assert serialized["metadata"] == final.metadata
            assert serialized["status"] == final.status.value
            assert final.metadata["action_type"] == "task_complete"
            assert final.metadata["task_id"] == "task-1"
            assert final.status == (MessageStatus.ERROR if scenario == "cancelled" else MessageStatus.FINISHED)
            if scenario != "cancelled":
                assert final.message == result["message"]
                assert final.metadata["success"] is (scenario == "success")
            if scenario == "refusal":
                assert final.metadata["authAssistanceDeclined"] is True
            if failed:
                assert final.metadata["browser_cleanup"] == receipt, (scenario, final.metadata)
            else:
                assert "browser_cleanup" not in final.metadata


async def test_manager_cancelled_browser_pause_event_is_task_complete():
    """Workflow-owned cancel must persist the durable browser terminal.

    Production agent 043e4578 (2026-09-06) proved that Temporal TRY_CANCEL can
    acknowledge cancellation after the activity saved its recording but before
    the activity's best-effort task_complete write lands. The manager is the
    authoritative observer of cancellation, so its task-scoped event must carry
    the publisher's task_complete contract rather than only session_paused.
    """
    from domains.spawn_browser_agent_v3.handler import SpawnBrowserAgentManagerV3
    from tools.base import EventType, MessageStatus

    class _FakeActivityHandle:
        def done(self):
            return True

        def cancel(self):
            raise AssertionError("done activity should not be cancelled")

        def __await__(self):
            async def _result():
                return {
                    "status": "cancelled",
                    "task_id": "task-1",
                    "browser_url": "https://steel.example/debug",
                    "session_id": "session-1",
                }

            return _result().__await__()

    workflow_instance = SimpleNamespace(
        user_id="user-1",
        agent_id="agent-1",
        is_paused=False,
        write_lock_enabled=True,
        system_name="Rose",
    )
    manager = SpawnBrowserAgentManagerV3()

    with (
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.start_activity",
            return_value=_FakeActivityHandle(),
        ),
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.wait_condition",
            AsyncMock(return_value=None),
        ),
    ):
        events = []
        async for event in manager.execute_tool(workflow_instance, {"goal": "Buy socks"}, "tool-1"):
            events.append(event)

    pause_event = events[-1]
    assert "paused" not in pause_event.message.lower()
    assert "userPauseRequested" not in pause_event.metadata
    assert pause_event.type == EventType.POST_MESSAGE
    assert pause_event.status == MessageStatus.ERROR
    assert pause_event.metadata == {
        "toolName": "spawn_browser_agent",
        "action_type": "task_complete",
        "task_id": "task-1",
        "browser_url": "https://steel.example/debug",
        "session_id": "session-1",
    }


async def test_manager_cancelled_browser_pause_preserves_preallocated_task_id(user_resumes=False, explicit_user=True):
    """TRY_CANCEL must not erase the browser task ownership key."""
    from domains.spawn_browser_agent_v3.handler import (
        SpawnBrowserAgentManagerV3,
        _logical_browser_task_id,
    )
    from tools.base import MessageStatus

    class _CancellingActivityHandle:
        cancelled = False

        def done(self):
            return False

        def cancel(self):
            self.cancelled = True
            if user_resumes:
                workflow_instance.is_paused = False
                workflow_instance._user_pause_active = False

        def __await__(self):
            async def _cancelled():
                raise asyncio.CancelledError

            return _cancelled().__await__()

    workflow_instance = SimpleNamespace(
        user_id="user-1",
        agent_id="11111111-1111-4111-8111-111111111111",
        is_paused=True,
        _user_pause_active=explicit_user,
        write_lock_enabled=True,
        system_name="Rose",
    )
    handle = _CancellingActivityHandle()
    start_calls = []

    def fake_start_activity(*args, **kwargs):
        start_calls.append((args, kwargs))
        return handle

    with (
        patch("domains.spawn_browser_agent_v3.handler.workflow.in_workflow", return_value=True),
        patch("domains.spawn_browser_agent_v3.handler.workflow.info", return_value=SimpleNamespace(run_id="cancel-run")),
        patch("domains.spawn_browser_agent_v3.handler.workflow.uuid4", return_value="cancel-attempt"),
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.start_activity",
            side_effect=fake_start_activity,
        ),
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.wait_condition",
            AsyncMock(return_value=None),
        ),
    ):
        events = []
        manager = SpawnBrowserAgentManagerV3()
        async for event in manager.execute_tool(workflow_instance, {"goal": "Buy socks"}, "tool-1"):
            events.append(event)

    expected_task_id = _logical_browser_task_id(workflow_instance.agent_id)
    assert handle.cancelled is True
    assert start_calls[0][1]["args"][4] == expected_task_id
    assert events[-1].status == MessageStatus.ERROR
    assert events[-1].metadata == {
        "toolName": "spawn_browser_agent",
        "action_type": "task_complete",
        "task_id": expected_task_id,
        **({"userPauseRequested": True} if explicit_user else {}),
    }


async def test_pause_intent_survives_resume_while_cancellation_joins():
    await test_manager_cancelled_browser_pause_preserves_preallocated_task_id(user_resumes=True)


async def test_automatic_browser_pause_never_claims_user_intent():
    await test_manager_cancelled_browser_pause_preserves_preallocated_task_id(explicit_user=False)


class _SequencedActivityHandle:
    def __init__(self, result):
        self._result = result

    def done(self):
        return True

    def cancel(self):
        raise AssertionError("a finished browser activity must not be cancelled")

    def __await__(self):
        async def _result():
            return self._result

        return _result().__await__()


