async def test_manager_passes_fast_mode_cache_for_browser_activity():
    """Browser activities must receive the workflow Fast Mode flag (re-enabled).

    Earlier builds forced False to disable browser FM; warm OAi demos need the
    flag so decisions soft-complete / replay and Kernel is zeroed.
    """
    from domains.spawn_browser_agent_v3.handler import SpawnBrowserAgentManagerV3

    class _FakeActivityHandle:
        def done(self):
            return True

        def cancel(self):
            raise AssertionError("done activity should not be cancelled")

        def __await__(self):
            async def _result():
                return {"status": "completed", "success": True, "message": "done"}

            return _result().__await__()

    workflow_instance = SimpleNamespace(
        user_id="user-1",
        agent_id="agent-1",
        is_paused=False,
        write_lock_enabled=True,
        system_name="Rose",
        fast_mode_cache_enabled=True,
        model="rose-labs/rose-1-ultra",
    )
    manager = SpawnBrowserAgentManagerV3()
    start_calls = []

    def fake_start_activity(*args, **kwargs):
        start_calls.append((args, kwargs))
        return _FakeActivityHandle()

    with (
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.start_activity",
            side_effect=fake_start_activity,
        ),
        patch(
            "domains.spawn_browser_agent_v3.handler.workflow.wait_condition",
            AsyncMock(return_value=None),
        ),
    ):
        events = []
        async for event in manager.execute_tool(workflow_instance, {"goal": "Buy socks"}, "tool-1"):
            events.append(event)

    assert events[-1].status.name == "FINISHED"
    # Positional args must bind to the activity's own parameters.
    import inspect

    from domains.spawn_browser_agent_v3.handler import spawn_browser_agent_activity_v3

    bound = inspect.signature(spawn_browser_agent_activity_v3).bind(*start_calls[0][1]["args"]).arguments
    assert bound["fast_mode_cache_enabled"] is True
    assert bound["world_model_mode"] is None
    # The browser agent inherits its spawning agent's model pool.
