def test_challenge_recovery_reuses_one_tool_call_id_for_every_stage():
    """Every recovery stage must update one streamed progress lifecycle."""
    import inspect

    from domains.spawn_browser_agent_v3.handler import (
        _browser_action_tool_call_id,
        _spawn_browser_agent_activity_v3_real,
    )

    llm_result = {"tool_call_id": "call_recovery_123"}

    assert _browser_action_tool_call_id(llm_result) == "call_recovery_123"
    assert _browser_action_tool_call_id(llm_result) == "call_recovery_123"

    # Cement the integration: all staged IN_PROGRESS and terminal events close
    # the exact tool call streamed by the browser-use model.
    activity_source = inspect.getsource(_spawn_browser_agent_activity_v3_real)
    recovery_branch = activity_source.split('if action_name == "recover_from_challenge":', 1)[1].split(
        'if action_name in ("attempt_completion", "done"):', 1
    )[0]
    assert "recovery_call_id = _browser_action_tool_call_id(llm_result)" in recovery_branch
    assert "tool_call_id=recovery_call_id" in recovery_branch
    assert "recovery_call_id = str(uuid_module.uuid4())" not in recovery_branch
    assert "status=MessageStatus.IN_PROGRESS" in recovery_branch
    assert 'if not bool(config_result.get("storage_state_preloaded")):' in recovery_branch
    assert "await _restore_rotation_storage_state(" in recovery_branch
    activity_source = inspect.getsource(_spawn_browser_agent_activity_v3_real)
    assert "recovery_call_id = _browser_action_tool_call_id(llm_result)" in recovery_branch


def test_challenge_recovery_call_keywords_match_callee_contract():
    """The live handler must not drift from the keyword-only recovery API."""
    import inspect

    from domains.spawn_browser_agent_v3.challenge_recovery import recover_from_challenge
    from domains.spawn_browser_agent_v3.handler import _spawn_browser_agent_activity_v3_real

    source = textwrap.dedent(inspect.getsource(_spawn_browser_agent_activity_v3_real))
    calls = [
        node
        for node in ast.walk(ast.parse(source))
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "recover_from_challenge"
    ]
    assert len(calls) == 1
    keywords = {keyword.arg: keyword.value for keyword in calls[0].keywords}
    assert set(keywords) <= set(inspect.signature(recover_from_challenge).parameters)
    assert ast.unparse(keywords["skip_cookie_probes"]) == (
        "provider_exit_rejected or escalate_after_cookie_false_stable"
    )


async def test_browser_tab_rebind_preserves_provider_keyboard_transport():
    """Exercise actual activity call kwargs, focus rebinding, and humanizer dispatch."""
    import ast
    import inspect
    import textwrap
    import browser_tools.humanizer as hm
    from domains.spawn_browser_agent_v3 import handler
    from domains.spawn_browser_agent_v3.tilion_worker import is_single_cdp_client_provider

    # Resolve the actual activity call expression, so omitting its policy keyword
    # cannot be hidden by a test that passes the new helper argument itself.
    tree = ast.parse(textwrap.dedent(inspect.getsource(handler._spawn_browser_agent_activity_v3_real)))
    calls = [n for n in ast.walk(tree) if isinstance(n, ast.Call)
             and isinstance(n.func, ast.Name) and n.func.id == '_rebind_browser_tab_runtime']
    assert len(calls) == 2

    class Gateway:
        def __init__(self, target):
            self.target = target
            self.in_flight = 0
            self.delivered = []
            self.timestamps = []
            self.cancelled = 0
        async def send(self, method, params=None):
            if method == 'Target.getTargetInfo':
                return {'targetInfo': {'targetId': self.target}}
            assert method == 'Input.dispatchKeyEvent'
            if self.in_flight:
                try:
                    await asyncio.Event().wait()
                except asyncio.CancelledError:
                    self.cancelled += 1
                    raise
            self.in_flight += 1
            try:
                await asyncio.sleep(0.01)
                self.timestamps.append(params['timestamp'])
                if params['type'] == 'char':
                    self.delivered.append(params['text'])
                return {}
            finally:
                self.in_flight -= 1
        async def detach(self):
            pass

    class Page:
        def __init__(self, target):
            self.gateway = Gateway(target)
            self.front_calls = 0
            self.viewport_size = {'width': 1280, 'height': 800}
            self.keyboard = SimpleNamespace()
        async def bring_to_front(self):
            self.front_calls += 1

    async def exercise(call, provider, same_page=False, cancel=False):
        a, b = Page('a'), Page('b')
        context = SimpleNamespace(pages=[a, b])
        async def new_cdp_session(page):
            return page.gateway
        context.new_cdp_session = new_cdp_session
        a.context = b.context = context
        closed = []
        async def close():
            closed.append(True)
        old = SimpleNamespace(close=close)
        recorder = SimpleNamespace(page=a)
        observer = lambda *_: None
        scope = dict(dom_service=SimpleNamespace(session=SimpleNamespace(agent_focus_target_id='a' if same_page else 'b')),
                     dom_page=None, playwright_browser=SimpleNamespace(contexts=[context]),
                     input_page=a, humanizer=old, browser_recorder=recorder, observe_cursor=observer,
                     tab_focus_cache=None, browser_session_metadata={'provider': provider},
                     is_single_cdp_client_provider=is_single_cdp_client_provider)
        kwargs = {k.arg: eval(compile(ast.Expression(k.value), '<actual-call-keyword>', 'eval'), scope)
                  for k in call.keywords}
        # Cursor initialization is unrelated I/O; all ownership and typing code is real.
        with patch.object(hm.BrowserHumanizer, 'initialize_cursor', new=AsyncMock()):
            selected, rebound = await handler._rebind_browser_tab_runtime(**kwargs)
        if same_page:
            assert selected is a and rebound is old and not closed and recorder.page is a
            return
        assert selected is b and recorder.page is b and closed == [True]
        assert a.front_calls == 0 and b.front_calls == 1
        assert rebound._cursor_observer is observer
        expected_serial = provider == 'tilion'
        # Type before checking policy so baseline proves the actual lost-key path.
        rebound._keycap = SimpleNamespace(next=lambda _: SimpleNamespace(dwell_s=0.001, interval_s=0.001))
        if expected_serial:
            if cancel:
                started = asyncio.Event()
                async def blocked(method, params=None):
                    started.set()
                    await asyncio.Event().wait()
                b.gateway.send = blocked
                task = asyncio.create_task(rebound.type_text('ab'))
                await started.wait()
                task.cancel()
                with pytest.raises(asyncio.CancelledError):
                    await task
                assert not rebound._movement_lock.locked()
            else:
                await rebound.type_text('ab')
                assert ''.join(b.gateway.delivered) == 'ab'
                assert b.gateway.timestamps == sorted(b.gateway.timestamps)
                assert b.gateway.in_flight == 0
        assert rebound._serial_cdp_keyboard is expected_serial
        await rebound.close()

    with patch.dict(os.environ, {'BROWSER_AGENT_CDP_MOUSE_TRANSPORT':'0',
                                'BROWSER_AGENT_IDLE_MOUSE_ENABLED':'0',
                                'BROWSER_AGENT_VISUAL_CURSOR_ENABLED':'0'}), \
         patch.object(hm, 'CDP_INPUT_DRAIN_TIMEOUT_SECONDS', 1.0):
        for call in calls:
            await exercise(call, 'tilion')
            await exercise(call, 'kernel')
            await exercise(call, 'steel')
            await exercise(call, 'tilion', same_page=True)
            await exercise(call, 'tilion', cancel=True)


async def test_cached_tab_focus_ignores_unrelated_stalled_page():
    """Known live focus must not await an unrelated tab's CDP attachment."""
    from domains.spawn_browser_agent_v3.handler import (
        TabFocusCache, _rebind_browser_tab_runtime,
        _synchronize_playwright_page_with_agent_focus,
    )

    class Page:
        def __init__(self, target):
            self.target = target
            self.closed = False
            self.front_calls = 0
            self.on_front = None
        def is_closed(self):
            return self.closed
        async def bring_to_front(self):
            self.front_calls += 1
            if self.on_front:
                await self.on_front()

    class Context:
        def __init__(self, pages):
            self.pages = pages
            self.lookups = []
            self.detached = []
            self.block = None
            self.on_lookup = None
        async def new_cdp_session(self, page):
            self.lookups.append(page.target)
            if page is self.block:
                await asyncio.Future()
            if self.on_lookup:
                self.on_lookup(page)
            context = self
            class Session:
                async def send(self, method):
                    assert method == "Target.getTargetInfo"
                    return {"targetInfo": {"targetId": page.target}}
                async def detach(self):
                    context.detached.append(page.target)
            return Session()

    foreign, focused = Page("foreign"), Page("focus")
    context = Context([foreign, focused])
    context.block = foreign
    cache = TabFocusCache()
    cache.target_ids[focused] = "focus"
    session = SimpleNamespace(agent_focus_target_id="focus")
    browser = SimpleNamespace(contexts=[context])
    service = SimpleNamespace(session=session)
    recorder = SimpleNamespace(page=foreign)
    old = SimpleNamespace(closed=False)
    async def close_old():
        old.closed = True
    old.close = close_old
    class Humanizer:
        def __init__(self, **kwargs):
            self.page = kwargs["input_page"]
        async def initialize_cursor(self, **kwargs):
            pass
        def set_cursor_observer(self, observer):
            self.observer = observer
    task = asyncio.create_task(_rebind_browser_tab_runtime(
        dom_service=service, dom_page=object(), playwright_browser=browser,
        current_page=foreign, humanizer=old, browser_recorder=recorder,
        cursor_observer=None, humanizer_factory=Humanizer, focus_cache=cache,
    ))
    try:
        for _ in range(3):
            await asyncio.sleep(0)
        assert task.done(), "known focus blocked behind unrelated CDP attachment"
        selected, rebound = await task
        assert selected is focused and rebound.page is focused
        assert old.closed and recorder.page is focused
        assert context.lookups == [] and focused.front_calls == 1
    finally:
        if not task.done():
            task.cancel()
            with contextlib.suppress(asyncio.CancelledError):
                await task

    async def select(ctx, current, target, cached=None, other_context=None):
        local_cache = cached or TabFocusCache()
        owner = SimpleNamespace(agent_focus_target_id=target)
        result = await _synchronize_playwright_page_with_agent_focus(
            dom_service=SimpleNamespace(session=owner),
            playwright_browser=SimpleNamespace(contexts=[ctx] + ([other_context] if other_context else [])),
            current_page=current, focus_cache=local_cache,
        )
        return result, local_cache

    # A closed or removed cached Page cannot be selected.
    focused.closed = True
    context.block = None
    result, _ = await select(context, foreign, "focus", cache)
    assert result is foreign and focused.front_calls == 1
    focused.closed = False
    context.pages = [foreign]
    result, _ = await select(context, foreign, "focus", cache)
    assert result is foreign and focused.front_calls == 1

    # A matching Page in another context is not an authority to cross contexts.
    result, _ = await select(context, foreign, "focus", cache, Context([focused]))
    assert result is foreign and focused.front_calls == 1

    # Focus changes select the new cached target, not the former focus.
    second = Page("second")
    context.pages = [foreign, focused, second]
    context.block = foreign
    cache.target_ids[second] = "second"
    result, _ = await select(context, focused, "second", cache)
    assert result is second and second.front_calls == 1

    # Existing uncached discovery and exact acquired-session cleanup still work.
    context.block = None
    context.lookups.clear()
    context.detached.clear()
    result, _ = await select(context, foreign, "focus")
    assert result is focused
    assert context.lookups == ["foreign", "focus"]
    assert context.detached == context.lookups

    # Target changes or removal while discovery awaits cannot authorize old focus.
    for mutation in ("focus", "removed", "closed", "context"):
        current, candidate = Page("current"), Page("candidate")
        ctx = Context([candidate, current])
        owner = SimpleNamespace(agent_focus_target_id="candidate")
        active_browser = SimpleNamespace(contexts=[ctx])
        def mutate(page):
            if mutation == "focus":
                owner.agent_focus_target_id = "new-target"
            elif mutation == "removed":
                ctx.pages.remove(page)
            elif mutation == "context":
                active_browser.contexts = [Context([current])]
            else:
                page.closed = True
        ctx.on_lookup = mutate
        result = await _synchronize_playwright_page_with_agent_focus(
            dom_service=SimpleNamespace(session=owner),
            playwright_browser=active_browser,
            current_page=current, focus_cache=TabFocusCache(),
        )
        assert result is current and candidate.front_calls == 0

    # A change during foregrounding is not published as a current selection.
    current, candidate = Page("current"), Page("candidate")
    ctx = Context([current, candidate])
    owner = SimpleNamespace(agent_focus_target_id="candidate")
    after_cache = TabFocusCache()
    after_cache.target_ids[candidate] = "candidate"
    async def change_during_front():
        owner.agent_focus_target_id = "replacement"
    candidate.on_front = change_during_front
    result = await _synchronize_playwright_page_with_agent_focus(
        dom_service=SimpleNamespace(session=owner),
        playwright_browser=SimpleNamespace(contexts=[ctx]), current_page=current,
        focus_cache=after_cache,
    )
    assert result is current and after_cache.foreground is None
    assert candidate.front_calls == 1  # Dispatched foreground cannot be retracted.

    # Cancellation of actual focus foregrounding propagates without publishing it.
    entered = asyncio.Event()
    async def blocked_front():
        entered.set()
        await asyncio.Future()
    focused.on_front = blocked_front
    context.pages = [foreign, focused]
    task = asyncio.create_task(select(context, foreign, "focus", cache))
    await entered.wait()
    task.cancel()
    try:
        await task
    except asyncio.CancelledError:
        pass
    else:
        raise AssertionError("focus cancellation swallowed")


async def test_playwright_page_tracks_browser_use_tab_focus():
    """Humanized clicks, recorder, and live view must follow browser-use focus."""
    import inspect

    from domains.spawn_browser_agent_v3.handler import (
        _rebind_browser_tab_runtime,
        _spawn_browser_agent_activity_v3_real,
    )

    class FakeCdpSession:
        def __init__(self, target_id):
            self.target_id = target_id
            self.detached = False

        async def send(self, method):
            assert method == "Target.getTargetInfo"
            return {"targetInfo": {"targetId": self.target_id}}

        async def detach(self):
            self.detached = True

    class FakePage:
        def __init__(self, target_id, url):
            self.target_id = target_id
            self.url = url
            self.front_calls = 0
            self.mutated = False
            page = self

            class FakeMouse:
                async def move(self, *_args, **_kwargs):
                    return None

                async def down(self, *_args, **_kwargs):
                    return None

                async def up(self, *_args, **_kwargs):
                    page.mutated = True

            self.mouse = FakeMouse()

        async def bring_to_front(self):
            self.front_calls += 1

    class FakeContext:
        def __init__(self, pages):
            self.pages = pages
            self.sessions = []

        async def new_cdp_session(self, page):
            session = FakeCdpSession(page.target_id)
            self.sessions.append(session)
            return session

    page_a = FakePage("target-a", "https://doordash.example/orders")
    page_b = FakePage("target-b", "https://google.example/sorry")
    context = FakeContext([page_a, page_b])
    browser = SimpleNamespace(contexts=[context])
    dom_service = SimpleNamespace(session=SimpleNamespace(agent_focus_target_id="target-b"))

    old_humanizer = SimpleNamespace(closed=False)

    async def close_old_humanizer():
        old_humanizer.closed = True

    old_humanizer.close = close_old_humanizer
    recorder = SimpleNamespace(page=page_a)

    with (
        patch.dict(
            os.environ,
            {
                "BROWSER_AGENT_CDP_MOUSE_TRANSPORT": "0",
                "BROWSER_AGENT_IDLE_MOUSE_ENABLED": "0",
                "BROWSER_AGENT_VISUAL_CURSOR_ENABLED": "0",
            },
        ),
        patch("browser_tools.humanizer.asyncio.sleep", new=AsyncMock()),
    ):
        selected, rebound_humanizer = await _rebind_browser_tab_runtime(
            dom_service=dom_service,
            dom_page=SimpleNamespace(),
            playwright_browser=browser,
            current_page=page_a,
            humanizer=old_humanizer,
            browser_recorder=recorder,
            cursor_observer=None,
        )
        await rebound_humanizer.click_at_coords(100, 100)

    assert selected is page_b
    assert recorder.page is page_b
    assert old_humanizer.closed is True
    assert page_a.front_calls == 0
    assert page_b.front_calls == 1
    assert page_a.mutated is False
    assert page_b.mutated is True
    assert all(session.detached for session in context.sessions)

    activity_source = inspect.getsource(_spawn_browser_agent_activity_v3_real)
    assert "input_page, humanizer = await _rebind_browser_tab_runtime(" in activity_source


async def test_asyncio_browser_heartbeat_starves_when_event_loop_blocked():
    """Owning-boundary repro: an asyncio keepalive cannot outlive a blocked loop.

    Agent 37b7bb31 (2026-09-09): 3 then 6 concurrent Replicate/ChatGPT browsers
    all died in the same second with ``activity Heartbeat timeout`` after
    121s–7min of useful work. The 2026-07-02 keepalive was an asyncio task on
    the same loop as CDP/screenshots; ``time.sleep`` here is that starvation.
    """
    import contextlib

    calls: list[float] = []
    stop = asyncio.Event()

    async def _background_heartbeat() -> None:
        while not stop.is_set():
            calls.append(time_module.monotonic())
            with contextlib.suppress(asyncio.TimeoutError):
                await asyncio.wait_for(stop.wait(), timeout=0.05)

    task = asyncio.create_task(_background_heartbeat())
    await asyncio.sleep(0)
    before = len(calls)
    time_module.sleep(0.25)
    during = len(calls)
    stop.set()
    await task
    assert during == before, (
        f"asyncio keepalive must stay silent while the event loop is blocked, got {before}->{during}"
    )


async def test_browser_work_checkpoint_preserves_cancel_after_completed_await():
    """A completed wait_for child must not erase Temporal's cancellation latch."""
    from temporalio import activity
    from temporalio.testing import ActivityEnvironment
    from domains.spawn_browser_agent_v3.activity_heartbeat import browser_activity_checkpoint

    for cancelled in (False, True):
        environment = ActivityEnvironment()
        ready = asyncio.Event()
        page = asyncio.get_running_loop().create_future()
        events = []

        async def browser_work():
            try:
                ready.set()
                await asyncio.wait_for(page, timeout=60)
                browser_activity_checkpoint("calling browser model")
                events.append("paid-step")
            except asyncio.CancelledError:
                events.append("cancelled")
            finally:
                # A work checkpoint must not keep injecting cancellation into
                # recording finalization after it has entered the cleanup path.
                await asyncio.sleep(0)
                activity.heartbeat("recording cleanup")
                events.append("recording-saved")

        running = asyncio.create_task(environment.run(browser_work))
        await ready.wait()
        page.set_result({"url": "https://example.test"})
        if cancelled:
            environment.cancel()
        await running
        expected = ["cancelled" if cancelled else "paid-step", "recording-saved"]
        assert events == expected, f"browser continued work after cancellation: {events}"


async def test_browser_recovery_stops_after_cancelled_completed_await():
    """Nested recovery must not restart work after a bounded await loses Task.cancel."""
    from temporalio import activity
    from temporalio.testing import ActivityEnvironment
    from domains.spawn_browser_agent_v3.handler import _run_browser_supervisor_recovery

    operations = ["snapshot", "focus", "escape", "buttons", "reload", "message"]
    for mode, boundary in [("normal", "snapshot"), ("pending", "snapshot")] + [
        ("completed", operation) for operation in operations[:-1]
    ]:
        environment = ActivityEnvironment()
        ready = asyncio.Event()
        result = asyncio.get_running_loop().create_future()
        observed = []
        post_cancel = []

        async def operation(name, value=None):
            observed.append(name)
            if activity.is_cancelled():
                post_cancel.append(name)
            if name == boundary:
                ready.set()
                await result
            return value

        class Page:
            url = "https://example.test/"
            context = SimpleNamespace(pages=[])

            @property
            def keyboard(self):
                return self

            async def evaluate(self, script):
                return await operation("snapshot", {"url": self.url})

            async def bring_to_front(self):
                await operation("focus")

            async def press(self, key):
                await operation("escape")

            def locator(self, selector):
                return self

            async def all(self):
                return await operation("buttons", [])

            async def reload(self):
                await operation("reload")

        async def save_message(**kwargs):
            return await operation("message", True)

        async def work():
            try:
                await _run_browser_supervisor_recovery(
                    agent_id="cancel-recovery-root",
                    task_id="cancel-recovery-browser",
                    browser_url=Page.url,
                    tool_call_id="cancel-recovery-tool",
                    iteration=1,
                    reason="action_timeout",
                    input_page=Page(),
                    dom_service=None,
                    browser_turn_messages=[],
                    reload_page=True,
                )
                observed.append("returned")
            except asyncio.CancelledError:
                observed.append("cancelled")
            finally:
                await asyncio.sleep(0)
                activity.heartbeat("recording cleanup")
                observed.append("cleanup")

        with patch("domains.spawn_browser_agent_v3.handler.save_browser_action_message", new=save_message):
            running = asyncio.create_task(environment.run(work))
            await asyncio.wait_for(ready.wait(), timeout=10)
            if mode == "pending":
                environment.cancel()
            else:
                result.set_result(None)
                if mode == "completed":
                    asyncio.get_running_loop().call_soon(environment.cancel)
            await asyncio.wait_for(running, timeout=10)
        expected = (
            operations + ["returned", "cleanup"]
            if mode == "normal"
            else [*operations[: operations.index(boundary) + 1], "cancelled", "cleanup"]
        )
        assert observed == expected, f"{mode}/{boundary}: recovery continued after cancellation: {observed}"
        assert post_cancel == [], f"{mode}/{boundary}: side effects after cancellation latch: {post_cancel}"


async def test_browser_activity_heartbeat_survives_event_loop_block():
    """Thread pump must keep heartbeating while the browser event loop is blocked."""
    from domains.spawn_browser_agent_v3.activity_heartbeat import BrowserActivityHeartbeat

    calls: list[float] = []
    pump = BrowserActivityHeartbeat(
        keepalive_seconds=0.05,
        heartbeat_fn=lambda _msg=None: calls.append(time_module.monotonic()),
    )
    token = pump.register()
    try:
        before = len(calls)
        time_module.sleep(0.25)
        after = len(calls)
        assert after > before, f"expected heartbeats during event-loop block, got {before}->{after}"
    finally:
        pump.unregister(token)
        pump.shutdown()


async def test_browser_activity_heartbeat_replays_runtimeerror_on_activity_loop():
    """Temporal 1.18.1 heartbeats use create_task; replay them onto the activity loop."""
    from domains.spawn_browser_agent_v3.activity_heartbeat import BrowserActivityHeartbeat

    calls: list[str] = []

    def flaky_then_ok(msg=None):
        if threading.current_thread().name == "browser-activity-heartbeat":
            raise RuntimeError("no running event loop")
        calls.append(str(msg))

    pump = BrowserActivityHeartbeat(keepalive_seconds=0.05, heartbeat_fn=flaky_then_ok)
    token = pump.register()
    try:
        await asyncio.sleep(0.2)
        assert calls, "expected heartbeat replayed onto the activity event loop"
    finally:
        pump.unregister(token)
        pump.shutdown()


